package upgradeable

import "strings"

// Authority decides who may change what a [Proxy] points at.
//
// It is handed the identity of the caller -- the realm that crossed into the
// realm holding the Proxy. When a transaction is sent straight to that realm
// the caller is a user: pkgPath is empty and addr is the signer. When the
// call arrives through another realm, say a DAO executing a proposal, pkgPath
// names that realm and addr is the realm's own address.
//
// Both halves are passed because the two authorization styles on gno.land
// read different ones: an owner check compares addresses, a governance check
// compares realm paths. An implementation must read the half it means and
// ignore the other. In particular an empty pkgPath is not a realm -- it is
// every user call -- so a path check must reject it explicitly.
type Authority interface {
	Authorized(addr address, pkgPath string) bool
	String() string
}

// AddrAuthority authorizes exactly one address: the signer of a direct call,
// or a realm acting at that address.
type AddrAuthority struct {
	addr address
}

// NewAddrAuthority returns an Authority holding addr.
func NewAddrAuthority(addr address) *AddrAuthority {
	if !addr.IsValid() {
		panic(ErrBadAddress)
	}
	return &AddrAuthority{addr: addr}
}

func (a *AddrAuthority) Authorized(addr address, _ string) bool {
	return a != nil && addr.IsValid() && addr == a.addr
}

// Address returns the authorized address.
func (a *AddrAuthority) Address() address {
	if a == nil {
		return ""
	}
	return a.addr
}

func (a *AddrAuthority) String() string {
	if a == nil {
		return "addr:<nil>"
	}
	return "addr:" + a.addr.String()
}

// RealmAuthority authorizes a fixed set of realm paths, the shape r/gov/dao
// uses: a governance realm executes the upgrade, and the proxy recognizes it
// by the path it was deployed at rather than by an address.
//
// More than one path is allowed so that authority can be moved without a gap:
// list both the old and the new governance realm, let the new one take over,
// then narrow the list.
type RealmAuthority struct {
	paths []string
}

// NewRealmAuthority returns an Authority holding paths. It panics on an empty
// list rather than authorizing nobody, and on a blank or padded entry rather
// than storing one that can never match a caller -- or, for a blank one,
// matches every user call.
func NewRealmAuthority(paths ...string) *RealmAuthority {
	if len(paths) == 0 {
		panic(ErrNoAuthority)
	}
	out := make([]string, 0, len(paths))
	for _, p := range paths {
		if p == "" || p != strings.TrimSpace(p) {
			panic(ErrBadRealmPath)
		}
		out = append(out, p)
	}
	return &RealmAuthority{paths: out}
}

func (a *RealmAuthority) Authorized(_ address, pkgPath string) bool {
	if a == nil || pkgPath == "" {
		return false
	}
	for _, p := range a.paths {
		if p == pkgPath {
			return true
		}
	}
	return false
}

// Paths returns a copy of the authorized realm paths.
func (a *RealmAuthority) Paths() []string {
	if a == nil {
		return nil
	}
	dup := make([]string, len(a.paths))
	copy(dup, a.paths)
	return dup
}

func (a *RealmAuthority) String() string {
	if a == nil {
		return "realms:<nil>"
	}
	return "realms:" + strings.Join(a.paths, ",")
}

// AnyOf authorizes a caller that any of its members authorizes. It is the
// handover shape for the common case: hold an address authority while you are
// still deploying, add the governance realm, drop the address later.
type AnyOf struct {
	auths []Authority
}

// NewAnyOf returns an Authority satisfied by any of auths. It panics on an
// empty list or a nil member, both of which would silently weaken or void
// the check.
func NewAnyOf(auths ...Authority) *AnyOf {
	if len(auths) == 0 {
		panic(ErrNoAuthority)
	}
	out := make([]Authority, 0, len(auths))
	for _, a := range auths {
		if a == nil {
			panic(ErrNoAuthority)
		}
		out = append(out, a)
	}
	return &AnyOf{auths: out}
}

func (a *AnyOf) Authorized(addr address, pkgPath string) bool {
	if a == nil {
		return false
	}
	for _, sub := range a.auths {
		if sub.Authorized(addr, pkgPath) {
			return true
		}
	}
	return false
}

func (a *AnyOf) String() string {
	if a == nil {
		return "anyOf:<nil>"
	}
	parts := make([]string, 0, len(a.auths))
	for _, sub := range a.auths {
		parts = append(parts, sub.String())
	}
	return "anyOf(" + strings.Join(parts, " ") + ")"
}

package upgradeable

import "errors"

var (
	// ErrNoAuthority is raised when a Proxy is built, or handed, a nil
	// authority. There is no "nobody" authority: to end upgradeability,
	// Freeze it.
	ErrNoAuthority = errors.New("upgradeable: an authority is required")

	// ErrUnauthorized is raised when the caller is not the authority.
	ErrUnauthorized = errors.New("upgradeable: caller is not the authority")

	// ErrStaleRealm is raised when the threaded realm value is not the
	// caller's live cur -- a stashed or replayed capture.
	ErrStaleRealm = errors.New("upgradeable: realm value is not the caller's live cur")

	// ErrFrozen is raised by every mutating method once Freeze has run.
	ErrFrozen = errors.New("upgradeable: proxy is frozen")

	// ErrNoImpl is raised when the proxy is asked for an implementation it
	// does not have yet.
	ErrNoImpl = errors.New("upgradeable: no implementation is live")

	// ErrNotNested is raised when a candidate registers from a realm that is
	// not under the proxy realm's own path. See New and NewOpen.
	ErrNotNested = errors.New("upgradeable: candidate realm is not nested under this one")

	// ErrNotARealm is raised when a candidate registers from a user call
	// rather than from a deployed realm, so there is no path to record.
	ErrNotARealm = errors.New("upgradeable: only a deployed realm can register a candidate")

	// ErrNilImpl is raised when the registered implementation is nil.
	ErrNilImpl = errors.New("upgradeable: implementation is nil")

	// ErrUnknownPath is raised when accepting or withdrawing a path that has
	// no candidate registered against it.
	ErrUnknownPath = errors.New("upgradeable: no candidate registered at that path")

	// ErrNoHistory is raised by Rollback when nothing has been replaced yet.
	ErrNoHistory = errors.New("upgradeable: no previous release to roll back to")

	// ErrBadAddress is raised when an authority is built from an invalid
	// address.
	ErrBadAddress = errors.New("upgradeable: invalid address")

	// ErrBadRealmPath is raised when an authority is built from a realm path
	// that is blank or carries surrounding whitespace. Both are silent
	// lockouts: a blank entry matches every user call, and a padded one
	// matches no caller at all.
	ErrBadRealmPath = errors.New("upgradeable: authority realm paths must be non-blank and unpadded")
)

// Package upgradeable lets a realm at a permanent path serve behavior that
// can change.
//
// A gno.land package path is immutable. The VM keeper refuses MsgAddPackage
// at a path that already holds a package, and the one exception -- private
// = true in gnomod.toml -- buys redeployability by giving up importability,
// and starts the realm's globals over from nothing besides. So a realm other
// people import cannot have its code replaced. What it can do is decide at
// call time which object it calls, and that object can live in a realm
// deployed years later. There is no delegatecall here and imports resolve
// statically: the indirection is an ordinary interface value, handed over by
// the realm that implements it.
//
// [Proxy] is the bookkeeping for that. It holds the one live implementation,
// the candidates waiting to replace it, and the ones it used to be, with an
// [Authority] deciding who may move between them. What it deliberately does
// not hold is your state. State belongs in the realm at the permanent path,
// or in a realm of its own, so that replacing an implementation does not
// touch it -- see the counter example under r/ for both halves.
//
// This is a p/ package on purpose. Pure packages can never be redeployed, so
// the rules below cannot be swapped out from under the realm that relies on
// them, which is exactly the property an upgrade mechanism has to have.
//
// # Threading cur
//
// Every authority-sensitive method takes (_ int, rlm realm): the caller
// threads its own cur as data instead of crossing into this package. The
// leading int keeps rlm out of first position, where it would declare a
// crossing function. rlm.Previous() is then the realm that crossed into the
// caller -- the user sending the transaction, the governance realm executing
// a proposal, or the implementation realm registering itself -- and
// rlm.IsCurrent() is what makes that unforgeable: a realm value cannot be
// persisted, and a stale capture fails the check.
package upgradeable

import (
	"chain"
	"chain/runtime"
	"strings"
)

// Event types emitted on every state change, so an indexer can reconstruct
// which code served which block without replaying the realm.
const (
	ProposeEvent   = "UpgradeProposed"
	WithdrawEvent  = "UpgradeWithdrawn"
	AcceptEvent    = "UpgradeAccepted"
	RollbackEvent  = "UpgradeRolledBack"
	ForgetEvent    = "UpgradeHistoryDropped"
	ExtendEvent    = "UpgradeExtensionAdded"
	UnextendEvent  = "UpgradeExtensionDropped"
	FreezeEvent    = "UpgradeFrozen"
	AuthorityEvent = "UpgradeAuthorityTransferred"
)

// Release is one implementation: the object, and the realm that authored it.
//
// PkgPath is read off the crossing frame at registration, never taken as an
// argument, so it names the realm the code actually lives at. That is what
// makes it worth reviewing before an upgrade is accepted, and what lets a
// state realm recognize the live implementation later.
//
// Release is returned by value. The proxy's own copy stays unreachable from
// outside, so a reader cannot rewrite history.
type Release struct {
	pkgPath string
	impl    any
	height  int64
}

// PkgPath returns the realm path the implementation was registered from.
func (r Release) PkgPath() string { return r.pkgPath }

// Impl returns the implementation object.
func (r Release) Impl() any { return r.impl }

// Height returns the block height at which the implementation registered.
func (r Release) Height() int64 { return r.height }

// IsZero reports whether r is the zero Release, which is what accessors
// return alongside a false ok.
func (r Release) IsZero() bool { return r.pkgPath == "" }

// Proxy holds the live implementation and the bookkeeping around replacing
// it. Keep one as a realm-level variable; it persists with the realm.
type Proxy struct {
	auth    Authority
	live    *Release
	pending []*Release // kept sorted by pkgPath
	past     []*Release
	exts     []string // kept sorted; realms allowed to act as this one
	frozen   bool
	nested   bool
}

// New returns a Proxy whose candidates must register from a realm nested
// under the realm holding it: gno.land/r/you/app/impl/v1 under
// gno.land/r/you/app. Deploying under that prefix needs your namespace, so
// the pending set cannot be filled by strangers.
//
// It panics on a nil authority. Upgradeability with no authority is not
// "nobody can upgrade" -- to reach that, Freeze.
func New(auth Authority) *Proxy {
	return newProxy(auth, true)
}

// NewOpen is New without the nesting rule: any deployed realm may register a
// candidate and the authority alone decides. Use it when implementations
// come from outside your namespace. The cost is that anyone can add entries
// to the pending set, which lives in your realm's storage; Withdraw clears
// them.
func NewOpen(auth Authority) *Proxy {
	return newProxy(auth, false)
}

func newProxy(auth Authority, nested bool) *Proxy {
	if auth == nil {
		panic(ErrNoAuthority)
	}
	return &Proxy{
		auth:   auth,
		nested: nested,
	}
}

// Impl returns the live implementation, and panics with ErrNoImpl if nothing
// has been accepted yet. Realms call this on every request, so the panic is
// the honest answer: a proxy with no implementation has no behavior to serve.
func (p *Proxy) Impl() any {
	if p.live == nil {
		panic(ErrNoImpl)
	}
	return p.live.impl
}

// TryImpl returns the live implementation and whether there is one, for
// callers that would rather render an empty page than fail the transaction.
func (p *Proxy) TryImpl() (any, bool) {
	if p.live == nil {
		return nil, false
	}
	return p.live.impl, true
}

// Live returns the live release.
func (p *Proxy) Live() (Release, bool) {
	if p.live == nil {
		return Release{}, false
	}
	return *p.live, true
}

// LivePath returns the realm path of the live implementation, or "" if there
// is none. A state realm that wants to grant write access to whichever
// implementation is current compares its caller against this.
func (p *Proxy) LivePath() string {
	if p.live == nil {
		return ""
	}
	return p.live.pkgPath
}

// Pending returns the registered candidates, ordered by path.
func (p *Proxy) Pending() []Release {
	out := make([]Release, 0, len(p.pending))
	for _, r := range p.pending {
		out = append(out, *r)
	}
	return out
}

// History returns the releases this proxy has already served, oldest first.
// It excludes the live one, and Forget empties it.
func (p *Proxy) History() []Release {
	out := make([]Release, 0, len(p.past))
	for _, r := range p.past {
		out = append(out, *r)
	}
	return out
}

// Frozen reports whether upgradeability has ended.
func (p *Proxy) Frozen() bool { return p.frozen }

// Authority returns the current authority.
func (p *Proxy) Authority() Authority { return p.auth }

// Extensions returns the realm paths allowed to act as the realm holding this
// proxy, in sorted order.
//
// A realm path is fixed, so the exported functions of the realm holding this
// proxy can never grow. What can grow is the set of OTHER realms permitted to
// run against its state: a realm deployed later declares an interface of its
// own, asserts the live implementation to it, and calls through. That is how
// an application adds an entry point it did not ship with. See the
// "extending a frozen API" pattern in the repository docs.
//
// The state accessor in the realm holding this proxy is what consults this --
// nothing here reaches into your state on its own.
func (p *Proxy) Extensions() []string {
	dup := make([]string, len(p.exts))
	copy(dup, p.exts)
	return dup
}

// IsExtension reports whether pkgPath may act as the realm holding this proxy.
// Call it from the state accessor, alongside the check for the realm's own
// path.
func (p *Proxy) IsExtension(pkgPath string) bool {
	if pkgPath == "" {
		return false // a user call is not a realm
	}
	for _, e := range p.exts {
		if e == pkgPath {
			return true
		}
	}
	return false
}

// AddExtension permits pkgPath to act as the realm holding this proxy.
//
// This grants the authority no power it did not have. An authority that can
// Accept an arbitrary implementation can already run arbitrary code against
// the state; naming a second realm that may do the same widens what is
// reachable, not who decides. It does widen the surface a reviewer has to
// read, which is why Extensions is public and Render should show it.
//
// Caller: the authority.
func (p *Proxy) AddExtension(_ int, rlm realm, pkgPath string) {
	p.assertMutable()
	p.assertAuthorized(0, rlm)
	if pkgPath == "" || pkgPath != strings.TrimSpace(pkgPath) {
		panic(ErrBadRealmPath)
	}
	if p.IsExtension(pkgPath) {
		return
	}
	at := len(p.exts)
	for i, e := range p.exts {
		if pkgPath < e {
			at = i
			break
		}
	}
	p.exts = append(p.exts, "")
	copy(p.exts[at+1:], p.exts[at:])
	p.exts[at] = pkgPath
	chain.Emit(ExtendEvent, "realm", pkgPath)
}

// DropExtension revokes pkgPath. The extension realm stays deployed and keeps
// answering calls; it just stops being able to reach the state, so whatever it
// exposed starts panicking rather than disappearing.
//
// Caller: the authority.
func (p *Proxy) DropExtension(_ int, rlm realm, pkgPath string) {
	p.assertMutable()
	p.assertAuthorized(0, rlm)
	for i, e := range p.exts {
		if e == pkgPath {
			p.exts = append(p.exts[:i], p.exts[i+1:]...)
			chain.Emit(UnextendEvent, "realm", pkgPath)
			return
		}
	}
	panic(ErrUnknownPath)
}

// AssertAuthorized panics unless rlm's caller is the authority. It exists for
// wrappers that do work of their own before delegating -- a schema check
// before Accept, say -- so that an unauthorized caller is refused for the
// right reason rather than tripping over the wrapper's own validation first.
func (p *Proxy) AssertAuthorized(_ int, rlm realm) { p.assertAuthorized(0, rlm) }

// Propose registers impl as a candidate, filed under the path of the realm
// that is calling.
//
// That path comes off the crossing frame rather than from an argument, and
// that is the point of the whole mechanism: a candidate cannot claim to have
// been authored by a path it does not occupy. Whoever accepts it is
// therefore accepting code they can go and read at that path, and a state
// realm that gates writes on LivePath is gating on the same authenticated
// string.
//
// The implementation realm calls this from its own init, so deploying the
// new version is what nominates it. Nothing is served until the authority
// accepts. Re-registering from the same realm replaces that candidate, which
// is the retry path after a failed deployment.
func (p *Proxy) Propose(_ int, rlm realm, impl any) {
	p.assertMutable()
	if !rlm.IsCurrent() {
		panic(ErrStaleRealm)
	}
	if impl == nil {
		panic(ErrNilImpl)
	}

	prev := rlm.Previous()
	from := prev.PkgPath()
	if from == "" || prev.IsEphemeral() {
		// A user call has no path to record at all. An ephemeral one does
		// have a path -- `gnokey maketx run` executes in /e/<addr>/run --
		// but it does not outlive the transaction, so filing a candidate
		// under it records a path that will never hold the code it claims.
		// The emptiness check alone does not catch that one.
		panic(ErrNotARealm)
	}
	if p.nested && !isNested(rlm.PkgPath(), from) {
		panic(ErrNotNested)
	}

	p.setPending(&Release{
		pkgPath: from,
		impl:    impl,
		height:  runtime.ChainHeight(),
	})
	chain.Emit(ProposeEvent, "impl", from)
}

// Withdraw drops a candidate. The authority may drop any; a realm may always
// drop its own, which is how a superseded candidate stops costing storage
// without the authority having to act.
func (p *Proxy) Withdraw(_ int, rlm realm, pkgPath string) {
	p.assertMutable()
	if !rlm.IsCurrent() {
		panic(ErrStaleRealm)
	}
	if rlm.Previous().PkgPath() != pkgPath {
		p.assertAuthorized(0, rlm)
	}
	if !p.removePending(pkgPath) {
		panic(ErrUnknownPath)
	}
	chain.Emit(WithdrawEvent, "impl", pkgPath)
}

// Accept makes the candidate at pkgPath the live implementation, and files
// the one it replaces in History.
//
// This is the upgrade. It is a separate transaction from the deployment that
// registered the candidate, by a separate principal, which is what gives the
// authority something reviewable to act on -- the same two-phase shape
// gno.land itself uses when a chain parks a submission until an approver
// enables it.
func (p *Proxy) Accept(_ int, rlm realm, pkgPath string) {
	p.assertMutable()
	p.assertAuthorized(0, rlm)

	i := p.findPending(pkgPath)
	if i < 0 {
		panic(ErrUnknownPath)
	}
	rel := p.pending[i]
	p.removePending(pkgPath)

	from := ""
	if p.live != nil {
		from = p.live.pkgPath
		p.past = append(p.past, p.live)
	}
	p.live = rel
	chain.Emit(AcceptEvent, "impl", pkgPath, "replaced", from)
}

// Rollback puts the previous release back in front, and returns the one it
// displaces to the pending set so a fixed version can be re-accepted without
// redeploying it.
//
// This is why History is kept: the release objects stay reachable, and
// reachable is the only form of "still deployed" that matters here. It costs
// storage, which is what Forget is for once a version has proven itself.
func (p *Proxy) Rollback(_ int, rlm realm) {
	p.assertMutable()
	p.assertAuthorized(0, rlm)

	n := len(p.past)
	if n == 0 {
		panic(ErrNoHistory)
	}
	prev := p.past[n-1]
	p.past = p.past[:n-1]

	from := ""
	if p.live != nil {
		from = p.live.pkgPath
		p.setPending(p.live)
	}
	p.live = prev
	chain.Emit(RollbackEvent, "impl", prev.pkgPath, "replaced", from)
}

// Forget drops the history, releasing the old implementations. Rollback
// stops working -- there is nothing to roll back to -- so this is the "the
// current version has proven itself" move, not routine cleanup.
func (p *Proxy) Forget(_ int, rlm realm) {
	p.assertMutable()
	p.assertAuthorized(0, rlm)
	dropped := len(p.past)
	p.past = nil
	chain.Emit(ForgetEvent, "dropped", itoa(dropped))
}

// TransferAuthority hands the power to upgrade to auth. It panics on nil:
// there is no way to leave a proxy upgradeable by nobody, because that state
// is indistinguishable from a mistake. Freeze says it on purpose.
func (p *Proxy) TransferAuthority(_ int, rlm realm, auth Authority) {
	p.assertMutable()
	p.assertAuthorized(0, rlm)
	if auth == nil {
		panic(ErrNoAuthority)
	}
	old := p.auth.String()
	p.auth = auth
	chain.Emit(AuthorityEvent, "from", old, "to", auth.String())
}

// Freeze ends upgradeability for good. The live implementation keeps serving
// and nothing can replace it: no unfreeze, by design, because a proxy that
// can be thawed has not actually given anything up. This is how a realm
// graduates from "we are still fixing it" to something other realms can
// build on -- an interrealm contract is only as trustworthy as the least
// mutable realm behind it.
//
// It refuses to freeze with nothing live, which would leave the realm
// permanently unable to answer a call.
//
// Freezing finalizes the extension set. Whatever is registered survives (the
// frozen implementation may depend on it), but afterwards nothing can be added
// and -- because Drop is a mutation too -- nothing can be dropped. So a
// registered extension keeps its access to the realm's state for good. Review
// the extensions before you freeze; you cannot revoke one after.
func (p *Proxy) Freeze(_ int, rlm realm) {
	p.assertMutable()
	p.assertAuthorized(0, rlm)
	if p.live == nil {
		panic(ErrNoImpl)
	}
	p.frozen = true
	p.pending = nil
	p.past = nil
	// Extensions are deliberately kept. They are reachable code that the
	// frozen implementation may depend on, and dropping them here would
	// break entry points that were working a block ago -- a freeze should
	// fix the realm's behavior, not change it.
	chain.Emit(FreezeEvent, "impl", p.live.pkgPath)
}

// isNested reports whether child is parent, or sits under it. The trailing
// separators are what keep gno.land/r/you/appliance from counting as nested
// under gno.land/r/you/app.
func isNested(parent, child string) bool {
	return strings.HasPrefix(child+"/", parent+"/")
}

// findPending returns the index of the candidate at pkgPath, or -1.
func (p *Proxy) findPending(pkgPath string) int {
	for i, r := range p.pending {
		if r.pkgPath == pkgPath {
			return i
		}
	}
	return -1
}

// setPending inserts rel, or replaces the candidate already at its path.
// The slice is kept sorted so Pending and any Render built on it read the
// same way on every node.
func (p *Proxy) setPending(rel *Release) {
	if i := p.findPending(rel.pkgPath); i >= 0 {
		p.pending[i] = rel
		return
	}
	at := len(p.pending)
	for i, r := range p.pending {
		if rel.pkgPath < r.pkgPath {
			at = i
			break
		}
	}
	p.pending = append(p.pending, nil)
	copy(p.pending[at+1:], p.pending[at:])
	p.pending[at] = rel
}

// removePending drops the candidate at pkgPath, reporting whether one was
// there.
func (p *Proxy) removePending(pkgPath string) bool {
	i := p.findPending(pkgPath)
	if i < 0 {
		return false
	}
	p.pending = append(p.pending[:i], p.pending[i+1:]...)
	return true
}

func (p *Proxy) assertMutable() {
	if p.frozen {
		panic(ErrFrozen)
	}
}

func (p *Proxy) assertAuthorized(_ int, rlm realm) {
	if !rlm.IsCurrent() {
		panic(ErrStaleRealm)
	}
	caller := rlm.Previous()
	if !p.auth.Authorized(caller.Address(), caller.PkgPath()) {
		panic(ErrUnauthorized)
	}
}

// itoa avoids pulling ufmt in for one event attribute.
func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

// Package app is an upgradeable realm in a handful of forwarding functions.
//
// It answers a narrower question than [upgradeable] does. That package gives
// you a proxy and leaves the shape of your realm to you: your interface, your
// state, your entry points, all of them permanent. This one makes a different
// trade — it fixes the shape once, generically, so that nothing about your
// application is permanent except the path.
//
//	package todo
//
//	import "gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/app/v0"
//
//	const Admin = address("g1…")
//
//	var a = app.New(app.Owner(Admin))
//
//	func init(cur realm)                              { a.Bind(0, cur) }
//	func Call(cur realm, verb, payload string) string { return a.Call(0, cur, verb, payload) }
//	func Register(cur realm, h app.Handler)           { a.Register(0, cur, h) }
//	func Manage(cur realm, verb, arg string) string   { return a.Admin(0, cur, verb, arg) }
//	func Store(_ int, rlm realm) *app.Store           { return a.Store(0, rlm) }
//	func Render(path string) string                   { return a.Render(path) }
//
// That realm never needs to change again. Its API is [Handler]'s verb set,
// which is data; its state is a [Store], whose keys are data. A later
// implementation adds verbs and keys freely, and callers reach them through
// the same Call.
//
// # Why the forwards cannot be avoided
//
// Those six lines are the irreducible minimum. A `p/` package cannot declare
// crossing functions, and `MsgCall` reaches a function by name at a realm
// path — so every entry point a user calls has to be declared in your realm.
// What a pure package can do is make each one a single forward, which is what
// the methods below are shaped for. Copy the block; only Admin changes.
//
// # What you give up
//
// Typed entry points. `Call(cur, "transfer", payload)` is one signature
// forever, so gnoweb shows one function, arguments are strings you encode
// yourself, and a misspelled verb is a runtime panic rather than a
// compile-time error. If your API is small and you can name it now, declare it
// with [upgradeable] and keep your types.
//
// The two compose: an app realm can carry hand-written typed entry points
// beside Call, forwarding to Proxy() for dispatch. Start generic, add typed
// entry points for the verbs that settle.
package app

import (
	"errors"
	"strconv"
	"strings"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/upgradeable/v0"
)

var (
	// ErrNoHandler is raised when the app has no accepted implementation.
	ErrNoHandler = errors.New("app: no handler is live")

	// ErrNotAHandler is raised when the live implementation does not satisfy
	// Handler. Register admits only a Handler, so this is unreachable in
	// practice and cheap to rule out.
	ErrNotAHandler = errors.New("app: live implementation does not satisfy Handler")

	// ErrStaleRealm is raised when the threaded realm value is not the
	// caller's live cur.
	ErrStaleRealm = errors.New("app: realm value is not the caller's live cur")

	// ErrNotBound is raised when Bind has not run, so the app does not know
	// its own path and cannot tell its callers apart.
	ErrNotBound = errors.New("app: Bind has not been called from init")

	// ErrForbidden is raised when a realm that is neither the app nor a
	// registered extension asks for the store.
	ErrForbidden = errors.New("app: store is not reachable from this realm")

	// ErrUnknownVerb is raised by Admin for a verb it does not implement.
	ErrUnknownVerb = errors.New("app: unknown admin verb")

	// ErrNoSchema is raised when a handler declares no verbs. An app whose
	// API cannot be enumerated is the thing this package exists to avoid.
	ErrNoSchema = errors.New("app: a handler must declare at least one verb")
)

// Handler is what an implementation realm implements.
//
// Two methods. [Handler.Schema] declares the API as data — a verb set rather
// than a method set, which is what lets it grow past the realm that serves it.
// [Handler.Handle] answers one call, having been handed a payload the app has
// already decoded and checked against that declaration.
//
// Panic to fail; panics cross the realm boundary and abort the transaction.
type Handler interface {
	// Schema declares the verbs this handler answers. It must not be nil or
	// empty, and it should be a package-level value rather than rebuilt per
	// call — the app reads it on every dispatch.
	Schema() *Schema

	// Handle answers args.Verb(). Every declared parameter is present and
	// parses as its kind by the time this runs, so the accessors on Args do
	// not return errors.
	Handle(_ int, rlm realm, args *Args) string
}

// App is the proxy, the state and the dispatch, in one object to hold at
// realm level.
type App struct {
	proxy *upgradeable.Proxy
	data  *kv
	self  string
}

// Owner returns an authority for a single address. Re-exported so a realm
// using this package need not import [upgradeable] as well.
func Owner(addr address) upgradeable.Authority { return upgradeable.NewAddrAuthority(addr) }

// Governed returns an authority for one or more governance realm paths.
func Governed(paths ...string) upgradeable.Authority {
	return upgradeable.NewRealmAuthority(paths...)
}

// New returns an App whose implementations must be deployed under the app
// realm's own path.
func New(auth upgradeable.Authority) *App {
	return &App{proxy: upgradeable.New(auth), data: newKV()}
}

// NewOpen returns an App that accepts implementations from any realm. The
// authority still decides which one serves.
func NewOpen(auth upgradeable.Authority) *App {
	return &App{proxy: upgradeable.NewOpen(auth), data: newKV()}
}

// Bind teaches the app its own path, which is what every later caller check
// compares against. Call it once, from your realm's init:
//
//	func init(cur realm) { a.Bind(0, cur) }
//
// It is separate from New because a package-level var initializer runs before
// there is a realm frame to read the path from.
func (a *App) Bind(_ int, rlm realm) {
	if !rlm.IsCurrent() {
		panic(ErrStaleRealm)
	}
	a.self = rlm.PkgPath()
}

// Proxy exposes the underlying proxy, for realms that want typed entry points
// beside Call or their own Render.
func (a *App) Proxy() *upgradeable.Proxy { return a.proxy }

// The inspection surface. Render shows all of it as a page; these are the
// same facts as discrete values, which is what an operator wants from
// vm/qeval and what a monitor wants to poll.

// LivePath returns the realm path of the handler currently serving, or "".
func (a *App) LivePath() string { return a.proxy.LivePath() }

// PendingPaths returns the candidate handler paths awaiting acceptance.
func (a *App) PendingPaths() []string { return paths(a.proxy.Pending()) }

// HistoryPaths returns the handlers already served, oldest first. A non-empty
// result is what makes rollback available.
func (a *App) HistoryPaths() []string { return paths(a.proxy.History()) }

// Extensions returns the realms permitted to act as this app.
func (a *App) Extensions() []string { return a.proxy.Extensions() }

// Frozen reports whether upgradeability has ended.
func (a *App) Frozen() bool { return a.proxy.Frozen() }

// Authority describes who may upgrade.
func (a *App) Authority() string { return a.proxy.Authority().String() }

func paths(rs []upgradeable.Release) []string {
	out := []string{}
	for _, r := range rs {
		out = append(out, r.PkgPath())
	}
	return out
}

// handler returns the live handler.
func (a *App) handler() Handler {
	v, ok := a.proxy.TryImpl()
	if !ok {
		panic(ErrNoHandler)
	}
	h, ok := v.(Handler)
	if !ok {
		panic(ErrNotAHandler)
	}
	return h
}

// Call decodes payload against the live handler's declaration for verb, and
// dispatches.
//
// An unknown verb, a payload with the wrong number of fields, or a field that
// does not parse as its declared kind are all refused here, before the handler
// runs, with a message naming the verb and its signature.
func (a *App) Call(_ int, rlm realm, verb string, payload string) string {
	h := a.handler()
	sc := h.Schema()
	v, ok := sc.Lookup(verb)
	if !ok {
		panic(errors.New("app: unknown verb " + strconv.Quote(verb) +
			"; this app answers " + strings.Join(sc.Names(), ", ")))
	}
	args, err := decode(v, payload)
	if err != nil {
		panic(err)
	}
	return h.Handle(0, rlm, args)
}

// Schema returns the live handler's declaration, or nil if nothing is live.
func (a *App) Schema() *Schema {
	v, ok := a.proxy.TryImpl()
	if !ok {
		return nil
	}
	h, ok := v.(Handler)
	if !ok {
		return nil
	}
	return h.Schema()
}

// Verbs enumerates the API. This is the query a caller makes first.
func (a *App) Verbs() []string { return a.Schema().Names() }

// Signature returns one verb's declaration, or "" if it is not answered.
func (a *App) Signature(verb string) string { return a.Schema().Signature(verb) }

// SchemaJSON renders the API for tooling: enough to build a form without
// reading any Gno source.
func (a *App) SchemaJSON() string { return a.Schema().JSON() }

// Supports reports whether the live handler answers verb.
func (a *App) Supports(verb string) bool {
	_, ok := a.Schema().Lookup(verb)
	return ok
}

// Register nominates the calling realm's handler. Forward it from your realm
// and call it from the implementation's init.
//
// A handler that declares no verbs is refused here rather than at first call:
// an app whose API cannot be enumerated is the thing this package exists to
// avoid.
func (a *App) Register(_ int, rlm realm, h Handler) {
	if h == nil || len(h.Schema().Names()) == 0 {
		panic(ErrNoSchema)
	}
	a.proxy.Propose(0, rlm, h)
}

// candidate returns the registered handler at pkgPath.
func (a *App) candidate(pkgPath string) (Handler, bool) {
	for _, r := range a.proxy.Pending() {
		if r.PkgPath() == pkgPath {
			h, ok := r.Impl().(Handler)
			return h, ok
		}
	}
	return nil, false
}

// accept promotes a candidate, refusing an upgrade that would break callers
// unless force is set.
//
// This is the check a verb-dispatch API cannot have without a schema. Without
// it, a handler that quietly drops a verb its predecessor served is accepted
// happily and callers find out at runtime. With it, the drop is named before
// the upgrade lands.
func (a *App) accept(_ int, rlm realm, pkgPath string, force bool) {
	a.proxy.AssertAuthorized(0, rlm)
	next, ok := a.candidate(pkgPath)
	if ok && !force {
		if breaks := next.Schema().Diff(a.Schema()); len(breaks) > 0 {
			panic(errors.New("app: refusing a breaking upgrade to " + pkgPath +
				": " + strings.Join(breaks, "; ") +
				" — use the accept-breaking verb to override"))
		}
	}
	a.proxy.Accept(0, rlm, pkgPath)
}

// Store hands out a [Store] accessor to code running on this app's cur: the
// live handler, and any realm the authority has registered as an extension.
//
// A realm holding a perfectly valid cur of its own is refused, because that
// cur carries its own path. And because the accessor carries the cur and
// re-checks it on every operation, the grant cannot outlive this call frame:
// a handler that stashes the accessor aborts the transaction (a realm value
// cannot be persisted), so rollback and freeze can no longer be undermined by
// a captured reference. See [Store].
func (a *App) Store(_ int, rlm realm) *Store {
	a.access(0, rlm) // gate at acquisition, for an immediate, clear refusal
	return &Store{app: a, rlm: rlm}
}

// access validates that rlm may reach the data and returns it. It runs at
// acquisition and again on every Store operation, so a stale or foreign rlm
// is refused every time, not just when the accessor is minted -- which is the
// teeth behind Store being a per-call capability.
func (a *App) access(_ int, rlm realm) *kv {
	if !rlm.IsCurrent() {
		panic(ErrStaleRealm)
	}
	if a.self == "" {
		panic(ErrNotBound)
	}
	if c := rlm.PkgPath(); c != a.self && !a.proxy.IsExtension(c) {
		panic(errors.New(ErrForbidden.Error() + ": " + c))
	}
	return a.data
}

// Admin is the whole governance surface behind one entry point, so a realm
// using this package declares one function instead of one per governance
// action.
//
//	accept <path>     make a registered candidate live, unless its schema
//	                  would break a caller of the one it replaces
//	accept-breaking <path>
//	                  the same, allowing a breaking schema change
//	withdraw <path>   drop a candidate
//	rollback          restore the previous handler
//	forget            drop the rollback history
//	freeze            end upgradeability, permanently
//	extend <path>     let another realm act as this one
//	unextend <path>   revoke that
//	owner <address>   hand authority to an address
//	govern <paths>    hand authority to governance realms (comma-separated)
//
// Every one of them is authority-gated by the proxy, except that a realm may
// always withdraw its own candidate. Returns "ok", or panics.
func (a *App) Admin(_ int, rlm realm, verb string, arg string) string {
	switch verb {
	case "accept":
		a.accept(0, rlm, arg, false)
	case "accept-breaking":
		a.accept(0, rlm, arg, true)
	case "withdraw":
		a.proxy.Withdraw(0, rlm, arg)
	case "rollback":
		a.proxy.Rollback(0, rlm)
	case "forget":
		a.proxy.Forget(0, rlm)
	case "freeze":
		a.proxy.Freeze(0, rlm)
	case "extend":
		a.proxy.AddExtension(0, rlm, arg)
	case "unextend":
		a.proxy.DropExtension(0, rlm, arg)
	case "owner":
		a.proxy.TransferAuthority(0, rlm, Owner(address(arg)))
	case "govern":
		parts := strings.Split(arg, ",")
		paths := make([]string, 0, len(parts))
		for _, p := range parts {
			paths = append(paths, strings.TrimSpace(p))
		}
		a.proxy.TransferAuthority(0, rlm, Governed(paths...))
	default:
		panic(errors.New(ErrUnknownVerb.Error() + ": " + verb))
	}
	return "ok"
}

// Render is a gnoweb page describing the app's current wiring: what serves,
// what could, what it used to, who decides, and how much state there is.
func (a *App) Render(_ string) string {
	var b strings.Builder
	b.WriteString("# " + a.self + "\n\n")

	if path := a.proxy.LivePath(); path == "" {
		b.WriteString("_No handler accepted yet._\n\n")
	} else {
		b.WriteString("Serving: `" + path + "`\n\n")
	}
	b.WriteString("State: **" + strconv.Itoa(a.data.length()) + "** keys\n\n")
	b.WriteString("Authority: `" + a.proxy.Authority().String() + "`\n\n")

	if sc := a.Schema(); sc != nil {
		b.WriteString("## API\n\n" + sc.Markdown() + "\n")
	}

	if a.proxy.Frozen() {
		b.WriteString("**Frozen.** The handler can no longer be replaced.\n\n")
	}
	writeList(&b, "Extensions", a.proxy.Extensions())
	writeReleases(&b, "Awaiting acceptance", a.proxy.Pending())
	writeReleases(&b, "Previously", a.proxy.History())
	return b.String()
}

func writeList(b *strings.Builder, title string, items []string) {
	if len(items) == 0 {
		return
	}
	b.WriteString("## " + title + "\n\n")
	for _, s := range items {
		b.WriteString("- `" + s + "`\n")
	}
	b.WriteString("\n")
}

func writeReleases(b *strings.Builder, title string, rs []upgradeable.Release) {
	if len(rs) == 0 {
		return
	}
	b.WriteString("## " + title + "\n\n")
	for _, r := range rs {
		b.WriteString("- `" + r.PkgPath() + "` (height " +
			strconv.FormatInt(r.Height(), 10) + ")\n")
	}
	b.WriteString("\n")
}

package app

import (
	"encoding/csv"
	"errors"
	"strconv"
	"strings"
	"unicode/utf8"
)

// The wire format is one CSV record.
//
// CSV because it is in the standard library, because it quotes correctly --
// a task called `buy milk, eggs` survives a round trip, which a naive split
// on commas does not -- and because it is writable by hand on a gnokey
// command line. Fields are positional, in the order the verb declares them,
// which is why the schema forbids a required parameter after an optional one
// and why Diff treats a reordering as breaking.
//
//	Encode(addTask, "buy milk, eggs")  ->  "buy milk, eggs"   (quoted by csv)
//	Encode(transfer, "g1abc…", "42")   ->  "g1abc…,42"
//
// A verb with no parameters takes an empty payload.

// Args is a decoded, validated payload. A handler receives one and reads
// fields by name; the app has already checked that every field is present and
// parses as its declared kind, so the accessors do not return errors.
type Args struct {
	verb   Verb
	values []string
}

// Verb returns the name of the verb being called.
func (a *Args) Verb() string { return a.verb.Name }

// Signature returns the declaration this payload was checked against, which
// is worth putting in a panic message.
func (a *Args) Signature() string { return a.verb.Signature() }

// Raw returns the decoded fields in declaration order, for a handler that
// would rather loop than name them.
func (a *Args) Raw() []string {
	dup := make([]string, len(a.values))
	copy(dup, a.values)
	return dup
}

// index returns the position of name and whether a value was supplied.
// It panics if the verb has no such parameter: that is the handler asking for
// something it did not declare, which no payload can fix.
func (a *Args) index(name string, want Kind) (int, bool) {
	for i, p := range a.verb.Params {
		if p.Name != name {
			continue
		}
		if want != "" && p.Kind != want {
			panic(errors.New("app: " + a.verb.Name + ": parameter " + name +
				" is declared " + string(p.Kind) + ", read as " + string(want)))
		}
		return i, i < len(a.values)
	}
	panic(errors.New("app: " + a.verb.Name + " has no parameter " + name +
		"; its signature is " + a.verb.Signature()))
}

// Has reports whether an optional parameter was supplied.
func (a *Args) Has(name string) bool {
	_, ok := a.index(name, "")
	return ok
}

// String returns a string parameter, or "" if it was optional and omitted.
func (a *Args) String(name string) string {
	i, ok := a.index(name, KindString)
	if !ok {
		return ""
	}
	return a.values[i]
}

// Int returns an int parameter, or 0 if it was optional and omitted.
func (a *Args) Int(name string) int64 {
	i, ok := a.index(name, KindInt)
	if !ok {
		return 0
	}
	n, _ := strconv.ParseInt(a.values[i], 10, 64) // checked at decode
	return n
}

// Bool returns a bool parameter, or false if it was optional and omitted.
func (a *Args) Bool(name string) bool {
	i, ok := a.index(name, KindBool)
	if !ok {
		return false
	}
	return a.values[i] == "true"
}

// Address returns an address parameter, or the zero address if it was
// optional and omitted.
func (a *Args) Address(name string) address {
	i, ok := a.index(name, KindAddress)
	if !ok {
		return ""
	}
	return address(a.values[i])
}

// Encode builds a payload for v from values given in declaration order,
// validating each against its declared kind. Use it when one realm calls
// another app, so an encoding mistake fails where it was made.
func Encode(v Verb, values ...string) string {
	if err := checkArity(v, len(values)); err != nil {
		panic(err)
	}
	for i, val := range values {
		if err := v.Params[i].Kind.parse(val); err != nil {
			panic(fieldErr(v, i, err))
		}
	}
	if len(values) == 0 {
		return ""
	}
	// A lone empty field encodes to nothing at all -- csv does not quote an
	// empty field, so the record "" and the record with no fields are the
	// same bytes. Quote it explicitly so the payload says which it is.
	if len(values) == 1 && values[0] == "" {
		return `""`
	}
	// Fast path: when nothing needs quoting, a CSV record IS the fields
	// joined by commas, and building a csv.Writer to discover that costs
	// more than the whole rest of the call. See needsQuotes.
	plain := true
	for _, val := range values {
		if needsQuotes(val) {
			plain = false
			break
		}
	}
	if plain {
		return strings.Join(values, ",")
	}

	var b strings.Builder
	w := csv.NewWriter(&b)
	if err := w.Write(values); err != nil {
		panic(errors.New("app: " + v.Name + ": " + err.Error()))
	}
	w.Flush()
	if err := w.Error(); err != nil {
		panic(errors.New("app: " + v.Name + ": " + err.Error()))
	}
	return strings.TrimRight(b.String(), "\n")
}

// splitPlain splits a payload on commas in a single pass, reporting false the
// moment it meets a byte that gives commas a different meaning. The one pass
// is the point: bailing out and splitting separately doubles the interpreted
// work over the whole payload.
func splitPlain(payload string) ([]string, bool) {
	out := []string{}
	start := 0
	for i := 0; i < len(payload); i++ {
		switch payload[i] {
		case '"', '\r', '\n':
			return nil, false
		case ',':
			out = append(out, payload[start:i])
			start = i + 1
		}
	}
	return append(out, payload[start:]), true
}

// needsQuotes mirrors csv.Writer's rule exactly. Diverging from it would mean
// Encode produced something csv.Reader reads back differently, so this is
// copied rather than approximated: a field is quoted when it is the literal
// `\.`, when it contains a comma, quote, CR or LF, or when it begins with a
// space.
func needsQuotes(field string) bool {
	if field == "" {
		return false
	}
	if field == `\.` {
		return true
	}
	switch field[0] {
	case ' ', '\t', '\v', '\f':
		return true
	}
	// A leading non-ASCII space (U+00A0 and friends) is rare enough to hand
	// to the slow path rather than decode a rune for on every call.
	if field[0] >= utf8.RuneSelf {
		return true
	}
	// One pass, for the same reason splitPlain is one pass:
	// strings.ContainsAny is interpreted Gno and costs more over a short
	// field than the csv.Writer it is trying to avoid.
	for i := 0; i < len(field); i++ {
		switch field[i] {
		case ',', '"', '\r', '\n':
			return true
		}
	}
	return false
}

// checkArity reports whether n values can satisfy v.
func checkArity(v Verb, n int) error {
	req := v.Required()
	if n < req {
		return errors.New("app: " + v.Name + " needs at least " + strconv.Itoa(req) +
			" parameter(s), got " + strconv.Itoa(n) + "; signature is " + v.Signature())
	}
	if n > len(v.Params) {
		return errors.New("app: " + v.Name + " takes at most " + strconv.Itoa(len(v.Params)) +
			" parameter(s), got " + strconv.Itoa(n) + "; signature is " + v.Signature())
	}
	return nil
}

// fieldErr names the verb, the parameter and the signature, which is what a
// caller needs to fix the payload without reading the handler's source.
func fieldErr(v Verb, i int, err error) error {
	return errors.New("app: " + v.Name + ": parameter " + v.Params[i].Name +
		": " + err.Error() + "; signature is " + v.Signature())
}

// decode parses and validates a payload against v.
func decode(v Verb, payload string) (*Args, error) {
	values := []string{}
	if payload == "" {
		// Ambiguous on its own: no fields, or one empty field. The verb
		// decides. A required first parameter means an empty payload is that
		// parameter, empty -- which is what a gnokey caller passing "" for a
		// string means, and Encode spells `""` for the same case.
		if v.Required() >= 1 {
			values = []string{""}
		}
	} else if rec, plain := splitPlain(payload); plain {
		// Fast path: with no quote and no newline anywhere, no field is
		// quoted, so every comma is a separator and every field is literal
		// -- exactly what csv.Reader would return. splitPlain decides that
		// and does the split in one pass, because every string operation
		// here is interpreted Gno: two passes with strings.ContainsAny and
		// strings.Split costs more than the csv parse it replaces.
		values = rec
	} else {
		rec, err := csv.NewReader(strings.NewReader(payload)).Read()
		if err != nil {
			return nil, errors.New("app: " + v.Name + ": malformed payload: " + err.Error())
		}
		values = rec
	}
	if err := checkArity(v, len(values)); err != nil {
		return nil, err
	}
	for i, val := range values {
		if err := v.Params[i].Kind.parse(val); err != nil {
			return nil, fieldErr(v, i, err)
		}
	}
	return &Args{verb: v, values: values}, nil
}

package app

import (
	"errors"
	"strconv"
	"strings"
)

// A schema is what a handler says about itself: the verbs it answers, what
// each one takes, and what it gives back. Handlers declare one; the app reads
// it to enumerate the API, to validate payloads before dispatch, and to refuse
// an upgrade that would break a caller.
//
// This is the part a verb-dispatch API is usually missing. Without it, "the
// API" is whatever the live handler's switch statement happens to accept: not
// discoverable, not checkable, and free to change under callers without
// anything noticing. A schema makes it data, which is the same move that makes
// the API growable in the first place.
//
// What it is not is static typing. Gno has no reflection, so nothing here can
// look at your Go types. Validation happens at call time against declarations
// you wrote by hand, and a handler whose switch disagrees with its own schema
// is a bug the schema cannot catch.

// Kind is the type of one payload field. The set is deliberately small: these
// are the types that survive a string encoding without ambiguity.
type Kind string

const (
	KindString  Kind = "string"
	KindInt     Kind = "int"     // int64, base 10
	KindBool    Kind = "bool"    // "true" or "false"
	KindAddress Kind = "address" // bech32, validated
	KindNone    Kind = "none"    // a verb that returns nothing meaningful
)

// Valid reports whether k is a known kind.
func (k Kind) Valid() bool {
	switch k {
	case KindString, KindInt, KindBool, KindAddress, KindNone:
		return true
	}
	return false
}

// parse checks that v is a well-formed value of kind k.
func (k Kind) parse(v string) error {
	switch k {
	case KindString, KindNone:
		return nil
	case KindInt:
		if _, err := strconv.ParseInt(v, 10, 64); err != nil {
			return errors.New("expected an integer, got " + strconv.Quote(v))
		}
	case KindBool:
		if v != "true" && v != "false" {
			return errors.New("expected true or false, got " + strconv.Quote(v))
		}
	case KindAddress:
		if !address(v).IsValid() {
			return errors.New("expected an address, got " + strconv.Quote(v))
		}
	default:
		return errors.New("unknown kind " + string(k))
	}
	return nil
}

// Field is one parameter of a verb.
type Field struct {
	Name string
	Kind Kind
	Doc  string
	Opt  bool // may be omitted, and only at the end of the parameter list
}

// P declares a required parameter.
func P(name string, kind Kind, doc string) Field {
	return Field{Name: name, Kind: kind, Doc: doc}
}

// Opt declares an optional parameter. Optional parameters must come last, and
// appending one is the only way to add a parameter to a verb without breaking
// callers.
func Opt(name string, kind Kind, doc string) Field {
	return Field{Name: name, Kind: kind, Doc: doc, Opt: true}
}

// Verb is one operation's signature.
type Verb struct {
	Name   string
	Doc    string
	Result Kind
	Params []Field
}

// Op declares a verb.
func Op(name, doc string, result Kind, params ...Field) Verb {
	return Verb{Name: name, Doc: doc, Result: result, Params: params}
}

// Required returns how many leading parameters must be supplied.
func (v Verb) Required() int {
	n := 0
	for _, p := range v.Params {
		if p.Opt {
			break
		}
		n++
	}
	return n
}

// Signature renders the verb as a one-line declaration:
//
//	add(text:string, urgent:bool?) -> int
func (v Verb) Signature() string {
	var b strings.Builder
	b.WriteString(v.Name)
	b.WriteString("(")
	for i, p := range v.Params {
		if i > 0 {
			b.WriteString(", ")
		}
		b.WriteString(p.Name + ":" + string(p.Kind))
		if p.Opt {
			b.WriteString("?")
		}
	}
	b.WriteString(") -> " + string(v.Result))
	return b.String()
}

// Schema is a handler's whole API, sorted by verb name.
type Schema struct {
	verbs []Verb
}

// NewSchema validates and sorts the declarations. It panics on a schema that
// could not be served correctly: a blank or duplicate name, an unknown kind, a
// required parameter after an optional one, or a duplicate parameter name.
// Those are all authoring mistakes, and a handler carrying one should fail to
// deploy rather than mis-describe itself forever.
func NewSchema(verbs ...Verb) *Schema {
	s := &Schema{verbs: make([]Verb, 0, len(verbs))}
	for _, v := range verbs {
		if strings.TrimSpace(v.Name) == "" || v.Name != strings.TrimSpace(v.Name) {
			panic(errors.New("app: verb names must be non-blank and unpadded"))
		}
		if !v.Result.Valid() {
			panic(errors.New("app: verb " + v.Name + ": unknown result kind " + string(v.Result)))
		}
		if _, dup := s.Lookup(v.Name); dup {
			panic(errors.New("app: duplicate verb " + v.Name))
		}
		seenOpt := false
		for i, p := range v.Params {
			if strings.TrimSpace(p.Name) == "" || p.Name != strings.TrimSpace(p.Name) {
				panic(errors.New("app: verb " + v.Name + ": parameter names must be non-blank and unpadded"))
			}
			if !p.Kind.Valid() || p.Kind == KindNone {
				panic(errors.New("app: verb " + v.Name + ": parameter " + p.Name +
					" has unusable kind " + string(p.Kind)))
			}
			if p.Opt {
				seenOpt = true
			} else if seenOpt {
				// The encoding is positional, so a required parameter after an
				// optional one could never be supplied without the optional.
				panic(errors.New("app: verb " + v.Name + ": required parameter " +
					p.Name + " follows an optional one"))
			}
			for j := 0; j < i; j++ {
				if v.Params[j].Name == p.Name {
					panic(errors.New("app: verb " + v.Name + ": duplicate parameter " + p.Name))
				}
			}
		}
		at := len(s.verbs)
		for i, e := range s.verbs {
			if v.Name < e.Name {
				at = i
				break
			}
		}
		s.verbs = append(s.verbs, Verb{})
		copy(s.verbs[at+1:], s.verbs[at:])
		s.verbs[at] = v
	}
	return s
}

// Names returns the verb names, sorted.
func (s *Schema) Names() []string {
	if s == nil {
		return nil
	}
	out := make([]string, 0, len(s.verbs))
	for _, v := range s.verbs {
		out = append(out, v.Name)
	}
	return out
}

// Lookup returns the verb by name.
func (s *Schema) Lookup(name string) (Verb, bool) {
	if s == nil {
		return Verb{}, false
	}
	for _, v := range s.verbs {
		if v.Name == name {
			return v, true
		}
	}
	return Verb{}, false
}

// Verbs returns a copy of the declarations.
func (s *Schema) Verbs() []Verb {
	if s == nil {
		return nil
	}
	dup := make([]Verb, len(s.verbs))
	copy(dup, s.verbs)
	return dup
}

// Signature renders one verb, or "" if it is not declared.
func (s *Schema) Signature(name string) string {
	if v, ok := s.Lookup(name); ok {
		return v.Signature()
	}
	return ""
}

// Markdown renders the API as a table, for Render.
func (s *Schema) Markdown() string {
	if s == nil || len(s.verbs) == 0 {
		return "_No API declared._\n"
	}
	var b strings.Builder
	b.WriteString("| Verb | Payload | Returns | |\n|---|---|---|---|\n")
	for _, v := range s.verbs {
		params := make([]string, 0, len(v.Params))
		for _, p := range v.Params {
			f := p.Name + ":" + string(p.Kind)
			if p.Opt {
				f += "?"
			}
			params = append(params, f)
		}
		p := strings.Join(params, ", ")
		if p == "" {
			p = "—"
		}
		b.WriteString("| `" + v.Name + "` | `" + p + "` | `" + string(v.Result) +
			"` | " + v.Doc + " |\n")
	}
	return b.String()
}

// JSON renders the schema for tooling: a client can build a form from this
// without reading any Gno source.
func (s *Schema) JSON() string {
	var b strings.Builder
	b.WriteString(`{"verbs":[`)
	if s != nil {
		for i, v := range s.verbs {
			if i > 0 {
				b.WriteString(",")
			}
			b.WriteString(`{"name":` + jsonStr(v.Name) +
				`,"doc":` + jsonStr(v.Doc) +
				`,"result":` + jsonStr(string(v.Result)) +
				`,"params":[`)
			for j, p := range v.Params {
				if j > 0 {
					b.WriteString(",")
				}
				b.WriteString(`{"name":` + jsonStr(p.Name) +
					`,"kind":` + jsonStr(string(p.Kind)) +
					`,"doc":` + jsonStr(p.Doc) +
					`,"optional":` + strconv.FormatBool(p.Opt) + `}`)
			}
			b.WriteString(`]}`)
		}
	}
	b.WriteString(`]}`)
	return b.String()
}

// Diff reports what upgrading from prev to s would break for existing callers.
// An empty result means every payload that worked before still works.
//
// Breaking: a verb disappears, a parameter disappears or changes kind or
// position, a new required parameter appears, or a result kind changes.
// Not breaking: a new verb, a new optional parameter at the end, new
// documentation.
func (s *Schema) Diff(prev *Schema) []string {
	out := []string{}
	if prev == nil {
		return out
	}
	for _, old := range prev.verbs {
		nv, ok := s.Lookup(old.Name)
		if !ok {
			out = append(out, "verb "+old.Name+" removed")
			continue
		}
		if nv.Result != old.Result {
			out = append(out, "verb "+old.Name+": result changed from "+
				string(old.Result)+" to "+string(nv.Result))
		}
		for i, op := range old.Params {
			if i >= len(nv.Params) {
				out = append(out, "verb "+old.Name+": parameter "+op.Name+" removed")
				continue
			}
			np := nv.Params[i]
			if np.Name != op.Name {
				out = append(out, "verb "+old.Name+": parameter "+strconv.Itoa(i)+
					" renamed from "+op.Name+" to "+np.Name)
			}
			if np.Kind != op.Kind {
				out = append(out, "verb "+old.Name+": parameter "+op.Name+
					" changed from "+string(op.Kind)+" to "+string(np.Kind))
			}
			if np.Opt != op.Opt && !np.Opt {
				out = append(out, "verb "+old.Name+": parameter "+op.Name+
					" became required")
			}
		}
		for i := len(old.Params); i < len(nv.Params); i++ {
			if !nv.Params[i].Opt {
				out = append(out, "verb "+old.Name+": required parameter "+
					nv.Params[i].Name+" added")
			}
		}
	}
	return out
}

// jsonStr quotes and escapes a string for the JSON rendering above.
func jsonStr(s string) string {
	var b strings.Builder
	b.WriteString(`"`)
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		default:
			if r < 0x20 {
				b.WriteString(`\u00`)
				const hex = "0123456789abcdef"
				b.WriteByte(hex[(r>>4)&0xf])
				b.WriteByte(hex[r&0xf])
				continue
			}
			b.WriteRune(r)
		}
	}
	b.WriteString(`"`)
	return b.String()
}

package app

import "strconv"

// kv is the schema-free key/value data itself. It is unexported and never
// handed out: callers reach it only through a [Store], which gates every
// operation. Keeping the data and the accessor separate is what lets the
// accessor be a revocable capability while the data persists untouched.
//
// It exists because a struct's fields are as permanent as the realm that
// declares them: if your state is `type State struct { count int64 }` in a
// realm you can never redeploy, you can never add a second field. Keys are
// data, so a kv can grow forever. The trade is everything a type gives you:
// nothing is checked, values are strings, and a typo in a key is a silent
// empty read.
//
// # Where the writes land
//
// A kv is allocated by your realm, so Gno's storage-realm borrow persists
// every write in the realm that owns it -- not in the caller's. That is what
// lets an implementation realm mutate your state without holding any of it.
type kv struct {
	keys []string // sorted
	vals []string
}

func newKV() *kv { return &kv{} }

// find returns the insertion index for k and whether k is present.
func (s *kv) find(k string) (int, bool) {
	lo, hi := 0, len(s.keys)
	for lo < hi {
		mid := int(uint(lo+hi) >> 1)
		if s.keys[mid] < k {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return lo, lo < len(s.keys) && s.keys[lo] == k
}

func (s *kv) get(k string) string {
	if i, ok := s.find(k); ok {
		return s.vals[i]
	}
	return ""
}

func (s *kv) has(k string) bool {
	_, ok := s.find(k)
	return ok
}

func (s *kv) set(k, v string) {
	i, ok := s.find(k)
	if ok {
		s.vals[i] = v
		return
	}
	s.keys = append(s.keys, "")
	s.vals = append(s.vals, "")
	copy(s.keys[i+1:], s.keys[i:])
	copy(s.vals[i+1:], s.vals[i:])
	s.keys[i], s.vals[i] = k, v
}

func (s *kv) del(k string) bool {
	i, ok := s.find(k)
	if !ok {
		return false
	}
	s.keys = append(s.keys[:i], s.keys[i+1:]...)
	s.vals = append(s.vals[:i], s.vals[i+1:]...)
	return true
}

func (s *kv) length() int { return len(s.keys) }

func (s *kv) allKeys() []string {
	dup := make([]string, len(s.keys))
	copy(dup, s.keys)
	return dup
}

func (s *kv) keysWithPrefix(prefix string) []string {
	out := []string{}
	i, _ := s.find(prefix)
	for ; i < len(s.keys); i++ {
		k := s.keys[i]
		if len(k) < len(prefix) || k[:len(prefix)] != prefix {
			break
		}
		out = append(out, k)
	}
	return out
}

func (s *kv) getInt(k string) int64 {
	n, err := strconv.ParseInt(s.get(k), 10, 64)
	if err != nil {
		return 0
	}
	return n
}

func (s *kv) setInt(k string, v int64) { s.set(k, strconv.FormatInt(v, 10)) }

func (s *kv) addInt(k string, delta int64) int64 {
	n := s.getInt(k) + delta
	s.setInt(k, n)
	return n
}

// Store is the handler-facing accessor. It is NOT the data -- it is a
// permission to touch it, bound to the realm value it was issued for.
//
// This is what closes the capability leak. The old design handed out a raw
// pointer to the data, which a handler could stash in a package variable and
// keep using after it was rolled back or the realm was frozen. A Store holds
// the caller's realm value and re-checks it on every operation, so:
//
//   - It cannot be stashed. Assigning it to realm state persists the realm
//     value it carries, which the VM refuses ("cannot persist realm value"),
//     aborting the transaction. The capability cannot outlive the call.
//   - It cannot be replayed. Even held transiently, a Store whose frame has
//     returned fails IsCurrent() on its next use.
//
// So the grant lives and dies with the exact call frame that obtained it,
// which is the only window in which the caller is genuinely the live handler
// (or a registered extension). See [App.Store].
type Store struct {
	app *App
	rlm realm
}

// Get returns the value at k, or "" if absent. An absent key and a key set to
// "" read the same; use Has to tell them apart.
func (s *Store) Get(k string) string { return s.app.access(0, s.rlm).get(k) }

// Has reports whether k is present.
func (s *Store) Has(k string) bool { return s.app.access(0, s.rlm).has(k) }

// Set writes v at k.
func (s *Store) Set(k, v string) { s.app.access(0, s.rlm).set(k, v) }

// Delete removes k, reporting whether it was there.
func (s *Store) Delete(k string) bool { return s.app.access(0, s.rlm).del(k) }

// Len returns the number of keys.
func (s *Store) Len() int { return s.app.access(0, s.rlm).length() }

// Keys returns a copy of the keys, in order.
func (s *Store) Keys() []string { return s.app.access(0, s.rlm).allKeys() }

// KeysWithPrefix returns the keys under a prefix, in order. Prefixes are how
// a Store holds more than one collection: "task/1", "task/2", "meta/owner".
func (s *Store) KeysWithPrefix(prefix string) []string {
	return s.app.access(0, s.rlm).keysWithPrefix(prefix)
}

// GetInt reads k as an int64, returning 0 if it is absent or unparsable.
func (s *Store) GetInt(k string) int64 { return s.app.access(0, s.rlm).getInt(k) }

// SetInt writes an int64 at k.
func (s *Store) SetInt(k string, v int64) { s.app.access(0, s.rlm).setInt(k, v) }

// AddInt adds delta to k and returns the new value.
func (s *Store) AddInt(k string, delta int64) int64 { return s.app.access(0, s.rlm).addInt(k, delta) }

package home

import (
	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/upgradeable/v0"
	"gno.land/p/nt/avl/v0"
)

// Test hooks. Realm globals live for the whole test binary, so every test
// that reads Render or Manifest starts from a known tree and a fresh proxy.

// ResetForTest clears all realm state.
func ResetForTest() {
	slots = avl.NewTree()
	rev = 0
	lastHeight = 0
	proxy = upgradeable.New(upgradeable.NewAddrAuthority(Admin))
}

// SeedForTest writes a slot without the authority check.
func SeedForTest(slug, body string) {
	rev++
	slots.Set(slug, &Slot{Body: body, Rev: rev, Height: 0})
}

// ReservedSlugsForTest exposes the reserved names.
func ReservedSlugsForTest() []string { return reservedSlugs }

// Package home is the realm behind https://gno.land/u/clockwork.
//
// gnoweb builds a user profile page by calling Render("") on the realm at the
// exact path /r/<username>/home (gno.land/pkg/gnoweb/handler_http.go,
// GetUserView). That lookup does no version resolution, so this path is the
// interface with gnoweb and can never carry a /vN suffix. Everything that
// might want to change therefore lives behind the path, in four layers:
//
//  1. CONTENT is data. The page is assembled from SLOTS: named markdown
//     fragments in an avl tree, each written by its own Set call. Updating
//     one paragraph is one small transaction.
//  2. LAYOUT is data. The slot named "layout" is the page template; every
//     :slug: placeholder in it is filled from the slot of that name.
//  3. STYLE is data. Slots under the "style." prefix are knobs (colors,
//     header mode) that the theme reads. Changing the accent color is a Set.
//  4. RENDERING is code, but replaceable. A THEME is a separate realm nested
//     under this one that implements Theme and registers itself from its own
//     init. The authority accepts it through p/clockwork/upgradeable and can
//     roll it back. The slots never move: an upgrade replaces the code that
//     reads them, not the data. When no theme is live the built-in renderer
//     in render.gno serves the page, and the operator views (system, slots,
//     edit, manifest) are always served by this realm, so a theme that
//     panics can be rolled back from the page it cannot break.
//
// This realm holds state and forwards. It is deliberately small, because it
// is the one piece that can never be redeployed: it is importable by its
// themes, so it cannot be private, so AddPackage refuses a second deploy.
package home

import (
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"

	"chain/runtime"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/upgradeable/v0"
	"gno.land/p/nt/avl/v0"
)

// Admin is the initial authority: the only address that may write slots and
// accept, roll back or freeze a theme. It is a constant so a reviewer can read
// who controls the page without decoding chain state; TransferAuthority moves
// it afterwards.
//
// The value here is the standard test1 account, so the gnodev walkthrough in
// the README works unedited. `make build ADMIN=g1...` rewrites it for a real
// deployment.
const Admin = address("g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm")

const (
	// LayoutSlug names the slot used as the page template.
	LayoutSlug = "layout"

	// StylePrefix marks slots that are style knobs rather than content.
	// Style("accent", ...) reads the slot "style.accent".
	StylePrefix = "style."

	// maxSlugLen bounds a slot name so an index row stays readable.
	maxSlugLen = 64
)

// Theme is what a renderer realm promises. It is declared here, in the file
// that can never change, so every theme version agrees on one type identity.
//
// Render receives the render path ("" is the profile page) and returns
// markdown. The operator views (system, slots, edit, manifest) never reach a
// theme; for any other path it does not draw itself, a theme should return
// Fallback(path). A panic here aborts the query: there is no recovering a
// foreign realm's panic, so a broken theme shows an error until Rollback.
type Theme interface {
	Render(path string) string
}

// Slot is one named fragment of the page.
type Slot struct {
	Body   string
	Rev    int   // Revision() at the time of the last write to this slot
	Height int64 // block height of that write
}

var (
	proxy    *upgradeable.Proxy
	selfPath string

	slots      = avl.NewTree() // slug -> *Slot
	rev        int             // total writes accepted; bumps on every mutation
	lastHeight int64           // height of the most recent write
)

func init(cur realm) {
	// Captured rather than written as a constant, so links and the nesting
	// rule follow the path this code was actually deployed at.
	selfPath = cur.PkgPath()
	proxy = upgradeable.New(upgradeable.NewAddrAuthority(Admin))
}

// ---------------------------------------------------------------------------
// Authority

// assertAuthority panics unless the caller of the crossing function that owns
// cur is the current authority. It asks the proxy's Authority directly rather
// than going through proxy.AssertAuthorized, so content writes keep working
// after Freeze: freezing ends code upgrades, not editing.
func assertAuthority(cur realm) {
	caller := cur.Previous()
	if !proxy.Authority().Authorized(caller.Address(), caller.PkgPath()) {
		panic("home: restricted to the authority")
	}
}

// ---------------------------------------------------------------------------
// Slugs

// reservedSlugs are placeholders computed at render time (see render.gno). A
// slot may not take one of these names, so the page never depends on which
// of the two would win.
var reservedSlugs = []string{"chainid", "height", "owner", "realm", "rev", "slots", "theme", "updated"}

// validSlug reports whether slug is a legal slot name: 1..maxSlugLen bytes of
// [a-z0-9._-]. No ':' so a slug can never break out of its own :slug:
// placeholder, and no uppercase so a slot has exactly one name.
func validSlug(slug string) bool {
	if len(slug) == 0 || len(slug) > maxSlugLen {
		return false
	}
	for i := 0; i < len(slug); i++ {
		c := slug[i]
		switch {
		case c >= 'a' && c <= 'z', c >= '0' && c <= '9':
		case c == '-', c == '_', c == '.':
		default:
			return false
		}
	}
	return true
}

func assertWritableSlug(slug string) {
	if !validSlug(slug) {
		panic("home: invalid slug " + strconv.Quote(slug) +
			": want 1-" + strconv.Itoa(maxSlugLen) + " bytes of [a-z0-9._-]")
	}
	for _, r := range reservedSlugs {
		if slug == r {
			panic("home: reserved slug " + slug + " is computed at render time")
		}
	}
}

// ---------------------------------------------------------------------------
// Writes (authority only)

// Set creates or replaces the slot named slug. This is the ordinary update:
// one slot, one transaction. An empty body keeps the slot but empties it; use
// Delete to remove it.
func Set(cur realm, slug, body string) {
	assertAuthority(cur)
	assertWritableSlug(slug)
	write(slug, body)
}

// Append adds to the end of a slot, creating it when absent. It exists for a
// body too large for one transaction: Set the first chunk, Append the rest.
func Append(cur realm, slug, body string) {
	assertAuthority(cur)
	assertWritableSlug(slug)
	write(slug, Get(slug)+body)
}

// Delete removes a slot. Deleting the layout slot restores the theme's
// default layout.
func Delete(cur realm, slug string) {
	assertAuthority(cur)
	if _, removed := slots.Remove(slug); !removed {
		panic("home: no such slot: " + slug)
	}
	bump()
}

func write(slug, body string) {
	bump()
	slots.Set(slug, &Slot{Body: body, Rev: rev, Height: lastHeight})
}

func bump() {
	rev++
	lastHeight = runtime.ChainHeight()
}

// ---------------------------------------------------------------------------
// Reads (anyone, including themes)

// Get returns a slot body, or "" when the slot does not exist.
func Get(slug string) string {
	v := slots.Get(slug)
	if v == nil {
		return ""
	}
	return v.(*Slot).Body
}

// Has reports whether a slot exists, empty or not.
func Has(slug string) bool { return slots.Has(slug) }

// Lookup returns a copy of a slot and whether it exists.
func Lookup(slug string) (Slot, bool) {
	v := slots.Get(slug)
	if v == nil {
		return Slot{}, false
	}
	return *v.(*Slot), true
}

// Slugs returns every slot name, sorted.
func Slugs() []string {
	out := make([]string, 0, slots.Size())
	slots.Iterate("", "", func(key string, _ any) bool {
		out = append(out, key)
		return false
	})
	return out
}

// Each visits every slot in name order until fn returns true.
func Each(fn func(slug string, s Slot) bool) {
	slots.Iterate("", "", func(key string, value any) bool {
		return fn(key, *value.(*Slot))
	})
}

// Style returns the style knob named key (the slot "style."+key), or fallback
// when it is absent or empty.
func Style(key, fallback string) string {
	if v := Get(StylePrefix + key); v != "" {
		return v
	}
	return fallback
}

// Layout returns the layout slot, or "" when none has been set. Themes
// substitute their own default in that case.
func Layout() string { return Get(LayoutSlug) }

// Revision returns the total number of writes this realm has accepted. It
// changes on every mutation, so a client can cheaply tell "nothing moved".
func Revision() int { return rev }

// LastHeight returns the block height of the most recent write, or 0.
func LastHeight() int64 { return lastHeight }

// Manifest returns one tab-separated line per slot:
//
//	<slug>\t<rev>\t<bytes>\t<sha256 of body, hex>
//
// It is the diff surface scripts/sync.sh reads: one query tells it exactly
// which local file is out of date, without downloading any body.
func Manifest() string {
	var b strings.Builder
	slots.Iterate("", "", func(key string, value any) bool {
		s := value.(*Slot)
		sum := sha256.Sum256([]byte(s.Body))
		b.WriteString(key)
		b.WriteString("\t")
		b.WriteString(strconv.Itoa(s.Rev))
		b.WriteString("\t")
		b.WriteString(strconv.Itoa(len(s.Body)))
		b.WriteString("\t")
		b.WriteString(hex.EncodeToString(sum[:]))
		b.WriteString("\n")
		return false
	})
	return b.String()
}

// Path returns this realm's package path, e.g. "gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/home".
func Path() string { return selfPath }

// Link returns the gnoweb path of a render path on this realm:
// Link("") is "/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/home", Link("slots") is "/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/home:slots".
func Link(sub string) string {
	p := selfPath
	if i := strings.Index(p, "/"); i >= 0 {
		p = p[i:]
	}
	if sub == "" {
		return p
	}
	return p + ":" + sub
}

// ---------------------------------------------------------------------------
// Themes: the upgradeable part.
//
// A theme realm nested under this path (…/home/theme/vN) calls Register from
// its own init, so deploying it is what nominates it. Nothing serves until the
// authority runs Accept with that path, which is a separate transaction naming
// code anyone can go and read. Rollback puts the previous theme back.

// Register records the calling realm's theme as a candidate. The path filed
// is read off the crossing frame, never taken as an argument, so a candidate
// cannot claim to live somewhere it does not. Only realms nested under this
// one are admitted; a direct user call is refused.
func Register(cur realm, t Theme) { proxy.Propose(0, cur, t) }

// Accept makes the candidate at pkgPath the live theme. Authority only.
func Accept(cur realm, pkgPath string) { proxy.Accept(0, cur, pkgPath) }

// Withdraw drops a candidate. Authority only, except that a theme realm may
// always drop its own.
func Withdraw(cur realm, pkgPath string) { proxy.Withdraw(0, cur, pkgPath) }

// Rollback restores the previous theme and returns the current one to the
// pending set. Authority only.
func Rollback(cur realm) { proxy.Rollback(0, cur) }

// Forget drops the rollback history and the storage it holds. Authority only.
func Forget(cur realm) { proxy.Forget(0, cur) }

// Freeze ends theme upgrades permanently. Slots stay editable. Authority
// only, and there is no way back.
func Freeze(cur realm) { proxy.Freeze(0, cur) }

// TransferAuthority hands both editing and upgrading to another address.
func TransferAuthority(cur realm, to address) {
	proxy.TransferAuthority(0, cur, upgradeable.NewAddrAuthority(to))
}

// LivePath returns the realm path of the theme currently serving, or "".
func LivePath() string { return proxy.LivePath() }

// PendingPaths returns the candidate theme paths awaiting acceptance.
func PendingPaths() []string {
	out := []string{}
	for _, r := range proxy.Pending() {
		out = append(out, r.PkgPath())
	}
	return out
}

// HistoryPaths returns the themes this realm has already served, oldest
// first, excluding the live one.
func HistoryPaths() []string {
	out := []string{}
	for _, r := range proxy.History() {
		out = append(out, r.PkgPath())
	}
	return out
}

// Frozen reports whether theme upgrades have ended.
func Frozen() bool { return proxy.Frozen() }

// Authority returns a human-readable description of who may write and
// upgrade.
func Authority() string { return proxy.Authority().String() }

// liveTheme returns the accepted theme, if any.
func liveTheme() (Theme, bool) {
	v, ok := proxy.TryImpl()
	if !ok {
		return nil, false
	}
	t, ok := v.(Theme)
	return t, ok
}

