package home

import (
	"strconv"
	"strings"

	"chain/runtime"
)

// Render is what gnoweb calls.
//
// The operator views (system, slots, edit, manifest) are always served here,
// never through the theme: a panic inside a foreign realm's code aborts the
// whole call and cannot be recovered from this side, so a theme that panics
// takes the page down until it is rolled back. These views are what the
// rollback is done from, and the routing keeps them out of the theme's reach.
// Every other path, the page itself included, goes to the live theme, or to
// the built-in renderer when none is accepted.
func Render(path string) string {
	if isOperatorPath(path) {
		return Fallback(path)
	}
	if t, ok := liveTheme(); ok {
		return t.Render(path)
	}
	return Fallback(path)
}

// operatorPaths are the render paths this realm keeps for itself.
var operatorPaths = []string{"system", "slots", "edit", "manifest"}

func isOperatorPath(path string) bool {
	path = cleanPath(path)
	for _, p := range operatorPaths {
		if path == p || strings.HasPrefix(path, p+"/") {
			return true
		}
	}
	return false
}

// cleanPath drops a query string from a render path.
func cleanPath(path string) string {
	if i := strings.Index(path, "?"); i >= 0 {
		return path[:i]
	}
	return path
}

// Fallback is the built-in renderer. Render routes the operator views here
// directly, and themes delegate to it for every other path they do not draw
// themselves, so these views exist under any theme:
//
//	""             the assembled page: the layout slot filled from the slots
//	"slots"        the slot index: name, size, revision, height of last write
//	"slots/<slug>" one slot's raw markdown, fenced
//	"edit"         forms that write slots (they build the gnokey command)
//	"edit/<slug>"  the same, prefilled with one slot
//	"system"       who may write, which theme is live, pending, history
//	"manifest"     Manifest() as plain text, for scripts
func Fallback(path string) string {
	path = cleanPath(path)
	switch {
	case path == "":
		return renderPage()
	case path == "slots":
		return renderIndex()
	case strings.HasPrefix(path, "slots/"):
		return renderSlot(strings.TrimPrefix(path, "slots/"))
	case path == "edit":
		return renderEdit("")
	case strings.HasPrefix(path, "edit/"):
		return renderEdit(strings.TrimPrefix(path, "edit/"))
	case path == "system":
		return renderSystem()
	case path == "manifest":
		return Manifest()
	}
	return "# Not found\n\nNo such path: " + strconv.Quote(path) +
		"\n\nTry [the slot index](" + Link("slots") + ").\n"
}

// ---------------------------------------------------------------------------
// Placeholder filling

// Filler substitutes :name: placeholders in a layout. It is lazy: a callback
// runs only when its placeholder occurs in the layout, so an unused slot is
// never even read. Substitution is single-pass and non-recursive, so a
// placeholder inside a slot body is left alone and no slot can expand into
// another. Names never contain ':', so no placeholder is a prefix of another
// and the result does not depend on registration order. A placeholder that
// nothing claims survives into the output verbatim: a missing section should
// be visible, not silently blank.
type Filler struct {
	names []string
	fns   map[string]func() string
}

// NewFiller returns a Filler with every slot and every computed placeholder
// registered. A theme adds its own widgets with Add before calling Fill.
func NewFiller() *Filler {
	f := &Filler{fns: map[string]func() string{}}
	slots.Iterate("", "", func(key string, value any) bool {
		s := value.(*Slot) // re-bound per iteration, so each closure sees its own
		f.Add(key, func() string { return s.Body })
		return false
	})
	f.Add("realm", func() string { return selfPath })
	f.Add("owner", Authority)
	f.Add("chainid", runtime.ChainID)
	f.Add("height", func() string { return strconv.FormatInt(runtime.ChainHeight(), 10) })
	f.Add("rev", func() string { return strconv.Itoa(rev) })
	f.Add("slots", slotLinks)
	f.Add("theme", func() string {
		if p := LivePath(); p != "" {
			return p
		}
		return "built-in"
	})
	f.Add("updated", updated)
	return f
}

// updated is the :updated: placeholder: when the slots last changed.
func updated() string {
	if lastHeight == 0 {
		return "never"
	}
	return "block " + strconv.FormatInt(lastHeight, 10) + " (rev " + strconv.Itoa(rev) + ")"
}

// Add registers the callback for :name:. A later Add for the same name wins,
// which is how a theme widget overrides a slot of the same name.
func (f *Filler) Add(name string, fn func() string) {
	if _, dup := f.fns[name]; !dup {
		f.names = append(f.names, name)
	}
	f.fns[name] = fn
}

// Fill returns layout with every present placeholder replaced.
func (f *Filler) Fill(layout string) string {
	pairs := []string{}
	for _, name := range f.names {
		ph := ":" + name + ":"
		if strings.Contains(layout, ph) {
			pairs = append(pairs, ph, f.fns[name]())
		}
	}
	if len(pairs) == 0 {
		return layout
	}
	return strings.NewReplacer(pairs...).Replace(layout)
}

// ---------------------------------------------------------------------------
// Views

// defaultLayout renders before a layout slot exists and no theme is live,
// i.e. right after the very first deploy. It uses only computed placeholders,
// so it never shows an unresolved :slug: of its own.
func defaultLayout() string {
	return "# " + selfPath + "\n\n" +
		"No theme is live and no layout slot is set, so this is the built-in page. " +
		"Content arrives with `Set`, one slot per call, and a theme deployed under " +
		"`" + selfPath + "/theme/` goes live with `Accept`. " +
		"See [system](" + Link("system") + ") and [edit](" + Link("edit") + ").\n\n" +
		"## Slots\n\n:slots:\n\n---\n\n" +
		"rev :rev: · block :height: · :chainid: · theme :theme: · " +
		"[edit](" + Link("edit") + ") · [system](" + Link("system") + ")\n"
}

func renderPage() string {
	layout := Layout()
	if layout == "" {
		layout = defaultLayout()
	}
	return NewFiller().Fill(layout)
}

// slotLinks is the :slots: placeholder: a bullet list of every slot, linking
// to its raw view.
func slotLinks() string {
	if slots.Size() == 0 {
		return "_no slots yet_"
	}
	var b strings.Builder
	slots.Iterate("", "", func(key string, _ any) bool {
		b.WriteString("- [" + key + "](" + Link("slots/"+key) + ")\n")
		return false
	})
	return strings.TrimSuffix(b.String(), "\n")
}

func renderIndex() string {
	var b strings.Builder
	b.WriteString("# Slots\n\n")
	b.WriteString("rev " + strconv.Itoa(rev) + " · " + strconv.Itoa(slots.Size()) + " slot(s) · " +
		"[edit](" + Link("edit") + ") · [system](" + Link("system") + ")\n\n")
	if slots.Size() == 0 {
		b.WriteString("_no slots yet_\n")
		return b.String()
	}
	b.WriteString("| slot | bytes | rev | height | |\n")
	b.WriteString("| --- | ---: | ---: | ---: | --- |\n")
	slots.Iterate("", "", func(key string, value any) bool {
		s := value.(*Slot)
		b.WriteString("| [" + key + "](" + Link("slots/"+key) + ") | " +
			strconv.Itoa(len(s.Body)) + " | " +
			strconv.Itoa(s.Rev) + " | " +
			strconv.FormatInt(s.Height, 10) + " | " +
			"[edit](" + Link("edit/"+key) + ") |\n")
		return false
	})
	return b.String()
}

func renderSlot(slug string) string {
	s, ok := Lookup(slug)
	if !ok {
		return "# Not found\n\nNo slot named " + strconv.Quote(slug) +
			".\n\nTry [the slot index](" + Link("slots") + ").\n"
	}
	f := fence(s.Body)
	var b strings.Builder
	b.WriteString("# " + slug + "\n\n")
	b.WriteString(strconv.Itoa(len(s.Body)) + " bytes · rev " + strconv.Itoa(s.Rev) +
		" · written at block " + strconv.FormatInt(s.Height, 10) +
		" · [edit](" + Link("edit/"+slug) + ")\n\n")
	b.WriteString(f + "\n" + s.Body)
	if !strings.HasSuffix(s.Body, "\n") {
		b.WriteString("\n")
	}
	b.WriteString(f + "\n")
	return b.String()
}

// fence returns a code fence longer than any backtick run in body, so the
// body can never close it early.
func fence(body string) string {
	longest, run := 0, 0
	for i := 0; i < len(body); i++ {
		if body[i] != '`' {
			run = 0
			continue
		}
		run++
		if run > longest {
			longest = run
		}
	}
	n := 3
	if longest >= 3 {
		n = longest + 1
	}
	return strings.Repeat("`", n)
}

// renderEdit is the in-browser editor: gnoweb forms that build the gnokey
// command for Set and Delete. Anyone can see them; only the authority's
// signature makes the resulting transaction succeed.
func renderEdit(slug string) string {
	var b strings.Builder
	b.WriteString("# Edit\n\n")
	b.WriteString("Writes are restricted to `" + Authority() + "`. Each form assembles the " +
		"`gnokey` command; sign it with that key. Slots and style knobs are the same thing: " +
		"`style.accent` is a slot too. [Index](" + Link("slots") + ") · [system](" + Link("system") + ")\n\n")

	if slug != "" {
		s, ok := Lookup(slug)
		if !ok {
			b.WriteString("> [!WARNING]\n> No slot named " + strconv.Quote(slug) + " yet. Saving creates it.\n\n")
		}
		b.WriteString("## " + slug + "\n\n")
		b.WriteString("<gno-form exec=\"Set\">\n")
		b.WriteString("  <gno-input name=\"slug\" type=\"text\" value=\"" + attr(slug) + "\" placeholder=\"slot name\" />\n")
		b.WriteString("  <gno-textarea name=\"body\" rows=\"10\" value=\"" + attr(s.Body) + "\" placeholder=\"markdown\" />\n")
		b.WriteString("</gno-form>\n\n")
		if ok {
			b.WriteString("[Raw view](" + Link("slots/"+slug) + ") · " +
				"a body that itself contains the two characters `\\n` or `\\t` is unfolded here; " +
				"use `make push` for those.\n\n")
		}
	} else {
		b.WriteString("## New or replace\n\n")
		b.WriteString("<gno-form exec=\"Set\">\n")
		b.WriteString("  <gno-input name=\"slug\" type=\"text\" placeholder=\"slot name: [a-z0-9._-]\" />\n")
		b.WriteString("  <gno-textarea name=\"body\" rows=\"10\" placeholder=\"markdown\" />\n")
		b.WriteString("</gno-form>\n\n")
	}

	b.WriteString("## Delete\n\n")
	b.WriteString("<gno-form exec=\"Delete\">\n")
	b.WriteString("  <gno-input name=\"slug\" type=\"text\" placeholder=\"slot name\" />\n")
	b.WriteString("</gno-form>\n\n")

	b.WriteString("## Slots\n\n")
	if slots.Size() == 0 {
		b.WriteString("_no slots yet_\n")
		return b.String()
	}
	slots.Iterate("", "", func(key string, _ any) bool {
		b.WriteString("- " + key + " · [view](" + Link("slots/"+key) + ") · [edit](" + Link("edit/"+key) + ")\n")
		return false
	})
	return b.String()
}

// attr escapes s for a double-quoted attribute of a gnoweb form tag, which
// must sit on one line: newlines and tabs become the \n and \t sequences the
// textarea unfolds.
func attr(s string) string {
	return strings.NewReplacer(
		"&", "&amp;",
		"\"", "&quot;",
		"<", "&lt;",
		">", "&gt;",
		"\r", "",
		"\n", "\\n",
		"\t", "\\t",
	).Replace(s)
}

// renderSystem shows the upgrade wiring and offers the Accept form.
func renderSystem() string {
	var b strings.Builder
	b.WriteString("# System\n\n")
	b.WriteString("| | |\n| --- | --- |\n")
	b.WriteString("| realm | `" + selfPath + "` |\n")
	b.WriteString("| authority | `" + Authority() + "` |\n")
	if p := LivePath(); p != "" {
		b.WriteString("| theme | [" + p + "](" + sourceLink(p) + ") |\n")
	} else {
		b.WriteString("| theme | built-in fallback (nothing accepted yet) |\n")
	}
	b.WriteString("| revision | " + strconv.Itoa(rev) + " |\n")
	b.WriteString("| last write | " + updated() + " |\n")
	if Frozen() {
		b.WriteString("| upgrades | **frozen** |\n")
	} else {
		b.WriteString("| upgrades | open |\n")
	}
	b.WriteString("\n")

	pending := PendingPaths()
	if len(pending) > 0 {
		b.WriteString("## Awaiting acceptance\n\n")
		b.WriteString("A theme registered itself by being deployed. Accepting is a separate transaction, " +
			"naming code you can [read first](" + sourceLink(pending[0]) + ").\n\n")
		for _, p := range pending {
			b.WriteString("<gno-form exec=\"Accept\">\n")
			b.WriteString("  <gno-input name=\"pkgPath\" type=\"text\" value=\"" + attr(p) + "\" placeholder=\"theme realm path\" />\n")
			b.WriteString("</gno-form>\n\n")
		}
	}

	if past := HistoryPaths(); len(past) > 0 {
		b.WriteString("## Previously\n\n")
		for _, p := range past {
			b.WriteString("- [" + p + "](" + sourceLink(p) + ")\n")
		}
		b.WriteString("\n")
	}

	if !Frozen() {
		b.WriteString("## Operations\n\n")
		b.WriteString("- [Rollback](" + helpLink("Rollback") + ") to the previous theme\n")
		b.WriteString("- [Accept](" + helpLink("Accept") + ") a theme by path\n")
		b.WriteString("- [Withdraw](" + helpLink("Withdraw") + ") a candidate\n")
		b.WriteString("- [Forget](" + helpLink("Forget") + ") the rollback history\n")
		b.WriteString("- [Transfer authority](" + helpLink("TransferAuthority") + ")\n")
		b.WriteString("- [Freeze](" + helpLink("Freeze") + "): no more theme upgrades, ever\n\n")
	}

	b.WriteString("## How an upgrade works\n\n")
	b.WriteString("1. Copy `theme/v0` to `theme/v1`, change what you like, keep `Render`.\n")
	b.WriteString("2. Deploy it at `" + selfPath + "/theme/v1`. Its init registers it here.\n")
	b.WriteString("3. Accept that path. The slots never moved; only the code reading them changed.\n")
	b.WriteString("4. If it misbehaves, Rollback. A theme that panics takes the page down until then, " +
		"but this view and the other built-in ones never go through the theme, so the rollback is always reachable.\n")
	return b.String()
}

func helpLink(fn string) string {
	return Link("") + "$help&func=" + fn
}

func sourceLink(pkgPath string) string {
	if i := strings.Index(pkgPath, "/"); i >= 0 {
		pkgPath = pkgPath[i:]
	}
	return pkgPath + "$source"
}

// Package theme is the first look of gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/home.
//
// It draws a header card as inline SVG, a divider and a footer, on top of the
// slot machinery the home realm provides. Everything else on the page comes
// from slots, so this file only decides HOW things are drawn, never WHAT is
// said.
//
// It is a candidate, not the page. Deploying it registers it (see init); the
// authority accepts it in a separate transaction. To change the look in a way
// slots and style knobs cannot express, copy this directory to theme/v1, edit,
// deploy, Accept. The home realm and every slot stay exactly where they are.
//
// Style knobs read from slots (all optional):
//
//	style.accent  #RRGGBB   brass by default
//	style.bg      #RRGGBB   card background
//	style.fg      #RRGGBB   card text
//	style.header  card | plain | none
//
// Widgets this theme adds to the layout, beside every slot and the home
// realm's computed placeholders:
//
//	:header:   the card (or a plain heading, or nothing, per style.header)
//	:divider:  a thin accent rule
//	:footer:   realm · revision · block · chain · theme · links
package theme

import (
	"encoding/base64"
	"strconv"
	"strings"

	"chain/runtime"

	"gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/home"
)

const (
	defaultAccent = "#D9A441"
	defaultBg     = "#14161C"
	defaultFg     = "#F4EFE6"
)

// DefaultLayout is what renders when no layout slot is set. content/layout.md
// starts as a copy of it; push that slot to depart from it.
const DefaultLayout = `:header:

<gno-columns>
![Clockwork](https://avatars.githubusercontent.com/u/6826762?s=400)
<gno-columns-sep />
:intro:

:links:
</gno-columns>

## Now

:now:

## Previously

:previously:

## Stack

:stack:

## Before the rabbit hole

:before:

## Numbers

:numbers:

:divider:

:about:

:footer:
`

type clockwork struct{}

var instance = &clockwork{}

// Instance returns the theme object, for a caller that would rather register
// it explicitly than rely on this realm's init having done it.
func Instance() home.Theme { return instance }

// init nominates this theme. Deploying is what registers it; it serves
// nothing until the authority runs Accept("<this path>").
func init(cur realm) {
	home.Register(cross(cur), instance)
}

// Render draws the profile page and hands every other path to the built-in
// views, so the editor and the system page look the same under any theme.
func (clockwork) Render(path string) string {
	if path != "" {
		return home.Fallback(path)
	}
	layout := home.Layout()
	if layout == "" {
		layout = DefaultLayout
	}
	f := home.NewFiller()
	f.Add("header", header)
	f.Add("divider", divider)
	f.Add("footer", footer)
	return f.Fill(layout)
}

// ---------------------------------------------------------------------------
// Widgets

func header() string {
	name := home.Get("name")
	if name == "" {
		name = home.Path()
	}
	tagline := home.Get("tagline")
	switch home.Style("header", "card") {
	case "none":
		return ""
	case "plain":
		out := "# " + name + "\n"
		if tagline != "" {
			out += "\n_" + tagline + "_\n"
		}
		return out
	}
	meta := home.Get("handle")
	if meta != "" {
		meta += " · "
	}
	meta += "rev " + strconv.Itoa(home.Revision()) +
		" · block " + strconv.FormatInt(runtime.ChainHeight(), 10)
	return image(name, card(name, tagline, meta))
}

func divider() string {
	accent := color("accent", defaultAccent)
	svg := `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 10" width="1200" height="10">` +
		`<defs><linearGradient id="g" x1="0" x2="1"><stop offset="0" stop-color="` + accent + `"/>` +
		`<stop offset="1" stop-color="` + accent + `" stop-opacity="0"/></linearGradient></defs>` +
		`<rect width="1200" height="10" rx="5" fill="url(#g)"/></svg>`
	return image("", svg)
}

func footer() string {
	theme := home.LivePath()
	if theme == "" {
		theme = "built-in"
	}
	return "`" + home.Path() + "` · rev " + strconv.Itoa(home.Revision()) +
		" · block " + strconv.FormatInt(runtime.ChainHeight(), 10) +
		" · " + runtime.ChainID() +
		" · theme `" + theme + "`" +
		" · [slots](" + home.Link("slots") + ")" +
		" · [edit](" + home.Link("edit") + ")" +
		" · [system](" + home.Link("system") + ")"
}

// ---------------------------------------------------------------------------
// SVG

// card draws the header: name, tagline and a meta line on a rounded panel,
// with a gear on the right. Text is clipped, not wrapped, so keep the
// tagline to one line.
func card(name, tagline, meta string) string {
	accent := color("accent", defaultAccent)
	bg := color("bg", defaultBg)
	fg := color("fg", defaultFg)

	var b strings.Builder
	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 300" width="1200" height="300" role="img" aria-label="`)
	b.WriteString(esc(name))
	b.WriteString(`"><defs><clipPath id="c"><rect width="1200" height="300" rx="24"/></clipPath>`)
	b.WriteString(`<clipPath id="t"><rect x="64" y="30" width="820" height="250"/></clipPath></defs>`)
	b.WriteString(`<g clip-path="url(#c)">`)
	b.WriteString(`<rect width="1200" height="300" fill="` + bg + `"/>`)
	b.WriteString(`<rect width="14" height="300" fill="` + accent + `"/>`)
	// The gear: a thick dashed ring reads as teeth without a single path command.
	b.WriteString(`<g transform="translate(1030 150)" fill="none" stroke="` + accent + `" opacity="0.9">`)
	b.WriteString(`<circle r="82" stroke-width="30" stroke-dasharray="21 15.8"/>`)
	b.WriteString(`<circle r="42" stroke-width="12"/>`)
	b.WriteString(`<circle r="11" fill="` + accent + `" stroke="none"/>`)
	b.WriteString(`</g>`)
	b.WriteString(`<g clip-path="url(#t)" fill="` + fg + `" font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif">`)
	b.WriteString(`<text x="64" y="132" font-size="76" font-weight="700">` + esc(name) + `</text>`)
	if tagline != "" {
		b.WriteString(`<text x="64" y="188" font-size="30" opacity="0.85">` + esc(tagline) + `</text>`)
	}
	b.WriteString(`<text x="64" y="246" font-size="24" fill="` + accent + `" font-family="ui-monospace, SFMono-Regular, Menlo, Consolas, monospace">` + esc(meta) + `</text>`)
	b.WriteString(`</g></g></svg>`)
	return b.String()
}

// image wraps an SVG document as a markdown image with a data: URI. gnoweb
// rejects every data: image except image/svg+xml, and gno.land's CSP allows
// data: in img-src, so this is the one way to draw without hosting anything.
func image(alt, svg string) string {
	alt = strings.NewReplacer("[", "", "]", "", "\n", " ").Replace(alt)
	return "![" + alt + "](data:image/svg+xml;base64," +
		base64.StdEncoding.EncodeToString([]byte(svg)) + ")"
}

// color returns the style knob when it is a well-formed #RRGGBB, else the
// default. Knobs are admin-written, but a value is still pasted into markup,
// so the shape is checked rather than trusted.
func color(key, fallback string) string {
	v := home.Style(key, fallback)
	if isHexColor(v) {
		return v
	}
	return fallback
}

func isHexColor(s string) bool {
	if len(s) != 7 || s[0] != '#' {
		return false
	}
	for i := 1; i < 7; i++ {
		c := s[i]
		switch {
		case c >= '0' && c <= '9', c >= 'a' && c <= 'f', c >= 'A' && c <= 'F':
		default:
			return false
		}
	}
	return true
}

// esc escapes text for an SVG element body or attribute.
func esc(s string) string {
	return strings.NewReplacer(
		"&", "&amp;",
		"<", "&lt;",
		">", "&gt;",
		"\"", "&quot;",
		"\n", " ",
	).Replace(s)
}

package theme

import (
	"encoding/base64"
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
	"gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/home"
)

const self = "gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/home/theme/v0"

// install stands in for the deploy-and-accept sequence: the harness does not
// deliver this realm's init as a transaction, so the registration is redone
// here, then accepted by the authority.
func install(cur realm) {
	testing.SetRealm(testing.NewCodeRealm(self))
	home.Register(cross(cur), instance)
	testing.SetRealm(testing.NewUserRealm(home.Admin))
	home.Accept(cross(cur), self)
}

func set(cur realm, slug, body string) {
	testing.SetRealm(testing.NewUserRealm(home.Admin))
	home.Set(cross(cur), slug, body)
}

// decodeCard pulls the SVG back out of the first data: image in out.
func decodeCard(t *testing.T, out string) string {
	const marker = "data:image/svg+xml;base64,"
	i := strings.Index(out, marker)
	if i < 0 {
		t.Fatalf("no svg image in output:\n%s", out)
	}
	rest := out[i+len(marker):]
	end := strings.Index(rest, ")")
	raw, err := base64.StdEncoding.DecodeString(rest[:end])
	uassert.NoError(t, err)
	return string(raw)
}

func TestRenderProfilePage(cur realm, t *testing.T) {
	if home.LivePath() != self {
		install(cur)
	}
	set(cur, "name", "Clockwork")
	set(cur, "tagline", "Lead Frontend Engineer <at> AiB")
	set(cur, "handle", "@clockworkgr")
	set(cur, "now", "shipping")

	out := home.Render("")
	uassert.True(t, strings.HasPrefix(out, "![Clockwork](data:image/svg+xml;base64,"), out)
	uassert.True(t, strings.Contains(out, "## Now\n\nshipping\n"), out)
	uassert.True(t, strings.Contains(out, "<gno-columns>"), out)
	uassert.True(t, strings.Contains(out, ":intro:"), "an unset slot stays visible: "+out)
	uassert.True(t, strings.Contains(out, "theme `"+self+"`"), out)
	uassert.True(t, strings.Contains(out, "[edit](/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/home:edit)"), out)

	svg := decodeCard(t, out)
	uassert.True(t, strings.Contains(svg, ">Clockwork</text>"), svg)
	uassert.True(t, strings.Contains(svg, "Lead Frontend Engineer &lt;at&gt; AiB"), "text is escaped: "+svg)
	uassert.True(t, strings.Contains(svg, "@clockworkgr · rev "), svg)
	uassert.True(t, strings.Contains(svg, `fill="#D9A441"`), "default accent: "+svg)
}

func TestStyleKnobs(cur realm, t *testing.T) {
	if home.LivePath() != self {
		install(cur)
	}
	set(cur, "name", "Clockwork")
	set(cur, "layout", ":header:\n\n:divider:\n")

	set(cur, "style.accent", "#00AAFF")
	svg := decodeCard(t, home.Render(""))
	uassert.True(t, strings.Contains(svg, `fill="#00AAFF"`), svg)

	set(cur, "style.accent", "red; injected")
	svg = decodeCard(t, home.Render(""))
	uassert.True(t, strings.Contains(svg, `fill="#D9A441"`), "a malformed color falls back: "+svg)
	uassert.False(t, strings.Contains(svg, "injected"))

	set(cur, "style.header", "plain")
	out := home.Render("")
	uassert.True(t, strings.HasPrefix(out, "# Clockwork\n"), out)
	uassert.True(t, strings.Contains(out, "data:image/svg+xml"), "the divider is still an image")

	set(cur, "style.header", "none")
	out = home.Render("")
	uassert.True(t, strings.HasPrefix(out, "\n\n![](data:image/svg+xml"), out)
}

func TestOtherPathsDelegate(cur realm, t *testing.T) {
	if home.LivePath() != self {
		install(cur)
	}
	uassert.True(t, strings.Contains(home.Render("slots"), "# Slots"))
	uassert.True(t, strings.Contains(home.Render("system"), "["+self+"]"))
	uassert.True(t, strings.Contains(home.Render("edit"), "<gno-form exec=\"Set\">"))
}

func TestHexColor(t *testing.T) {
	uassert.True(t, isHexColor("#abcdef"))
	uassert.True(t, isHexColor("#ABCDEF"))
	uassert.False(t, isHexColor("abcdef"))
	uassert.False(t, isHexColor("#abc"))
	uassert.False(t, isHexColor("#abcdeg"))
	uassert.False(t, isHexColor("#abcdef\" onload=\"x"))
}

// Package canvas is a fixed-size, 16-color pixel grid.
//
// It holds no chain state and knows nothing about payments: the realm
// gno.land/r/g1sw5xklxjjuv0yvuxy5f5s3l3mnj0nqq626a9wr/million/v0 wraps it with pricing and access control.
//
// Storage layout: one []byte per row, allocated on first paint. A row that
// was never painted is nil and costs nothing. Each byte holds a palette
// index; Blank (0) means "never painted".
package canvas

import (
	"errors"
	"strconv"
	"strings"
)

const (
	// Blank is the color of a pixel nobody painted. It cannot be painted.
	Blank byte = 0
	// MaxColor is the highest valid palette index.
	MaxColor byte = 15
	// MaxSide bounds width and height so x*y fits comfortably in an int.
	MaxSide = 10000
)

// Palette maps a color index to its CSS hex value. Index 0 is Blank and is
// rendered as white by clients.
var Palette = [MaxColor + 1]string{
	"#ffffff", // 0 blank
	"#ffffff", // 1 white
	"#e4e4e4", // 2 light gray
	"#888888", // 3 gray
	"#222222", // 4 black
	"#ffa7d1", // 5 pink
	"#e50000", // 6 red
	"#e59500", // 7 orange
	"#a06a42", // 8 brown
	"#e5d900", // 9 yellow
	"#94e044", // 10 lime
	"#02be01", // 11 green
	"#00d3dd", // 12 cyan
	"#0083c7", // 13 blue
	"#cf6ee4", // 14 magenta
	"#820080", // 15 purple
}

var (
	ErrOutOfRange   = errors.New("canvas: pixel out of range")
	ErrInvalidColor = errors.New("canvas: color must be between 1 and 15")
	ErrBadPixel     = errors.New("canvas: pixel must be x,y,color")
)

// Pixel is one paint request.
type Pixel struct {
	X, Y  int
	Color byte
}

// Canvas is a width x height grid of palette indexes.
type Canvas struct {
	width, height int
	rows          [][]byte
	painted       int
}

// New returns an empty canvas. It panics on a non-positive or oversized side.
func New(width, height int) *Canvas {
	if width <= 0 || height <= 0 || width > MaxSide || height > MaxSide {
		panic("canvas: width and height must be between 1 and " + strconv.Itoa(MaxSide))
	}
	return &Canvas{
		width:  width,
		height: height,
		rows:   make([][]byte, height),
	}
}

func (c *Canvas) Width() int  { return c.width }
func (c *Canvas) Height() int { return c.height }

// Painted is the number of pixels that are not Blank.
func (c *Canvas) Painted() int { return c.painted }

// Check reports whether p can be painted on this canvas.
func (c *Canvas) Check(p Pixel) error {
	if p.X < 0 || p.Y < 0 || p.X >= c.width || p.Y >= c.height {
		return ErrOutOfRange
	}
	if p.Color == Blank || p.Color > MaxColor {
		return ErrInvalidColor
	}
	return nil
}

// Get returns the color at (x, y). Out-of-range coordinates panic.
func (c *Canvas) Get(x, y int) byte {
	if x < 0 || y < 0 || x >= c.width || y >= c.height {
		panic(ErrOutOfRange)
	}
	row := c.rows[y]
	if row == nil {
		return Blank
	}
	return row[x]
}

// Set paints p. It panics when Check(p) fails.
func (c *Canvas) Set(p Pixel) {
	if err := c.Check(p); err != nil {
		panic(err)
	}
	row := c.rows[p.Y]
	if row == nil {
		row = make([]byte, c.width)
		c.rows[p.Y] = row
	}
	if row[p.X] == Blank {
		c.painted++
	}
	row[p.X] = p.Color
}

// Rows encodes rows [from, to) as one hex digit per pixel, row after row,
// with no separator. Clients slice it with the known width.
func (c *Canvas) Rows(from, to int) string {
	if from < 0 || to > c.height || from > to {
		panic(ErrOutOfRange)
	}
	var sb strings.Builder
	sb.Grow((to - from) * c.width)
	for y := from; y < to; y++ {
		row := c.rows[y]
		if row == nil {
			for x := 0; x < c.width; x++ {
				sb.WriteByte('0')
			}
			continue
		}
		for _, color := range row {
			sb.WriteByte(hexDigit(color))
		}
	}
	return sb.String()
}

// ParsePixels decodes "x,y,color;x,y,color;...". A trailing ';' is allowed.
// It validates the syntax and the color range but not the coordinates,
// which depend on the canvas: call Check for that.
func ParsePixels(s string) ([]Pixel, error) {
	s = strings.TrimSuffix(s, ";")
	if s == "" {
		return nil, ErrBadPixel
	}
	parts := strings.Split(s, ";")
	pixels := make([]Pixel, 0, len(parts))
	for _, part := range parts {
		fields := strings.Split(part, ",")
		if len(fields) != 3 {
			return nil, ErrBadPixel
		}
		x, err := strconv.Atoi(fields[0])
		if err != nil {
			return nil, ErrBadPixel
		}
		y, err := strconv.Atoi(fields[1])
		if err != nil {
			return nil, ErrBadPixel
		}
		color, err := ParseColor(fields[2])
		if err != nil {
			return nil, err
		}
		pixels = append(pixels, Pixel{X: x, Y: y, Color: color})
	}
	return pixels, nil
}

// ParseColor converts a decimal color index, rejecting Blank.
func ParseColor(s string) (byte, error) {
	n, err := strconv.Atoi(s)
	if err != nil || n <= int(Blank) || n > int(MaxColor) {
		return 0, ErrInvalidColor
	}
	return byte(n), nil
}

// Encode is the inverse of ParsePixels.
func Encode(pixels []Pixel) string {
	var sb strings.Builder
	for i, p := range pixels {
		if i > 0 {
			sb.WriteByte(';')
		}
		sb.WriteString(strconv.Itoa(p.X))
		sb.WriteByte(',')
		sb.WriteString(strconv.Itoa(p.Y))
		sb.WriteByte(',')
		sb.WriteString(strconv.Itoa(int(p.Color)))
	}
	return sb.String()
}

func hexDigit(v byte) byte {
	if v < 10 {
		return '0' + v
	}
	return 'a' + v - 10
}

package canvas

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestNewRejectsBadSizes(t *testing.T) {
	for _, tc := range []struct{ w, h int }{{0, 1}, {1, 0}, {-1, 1}, {MaxSide + 1, 1}, {1, MaxSide + 1}} {
		func() {
			defer func() {
				if r := recover(); r == nil {
					t.Errorf("New(%d, %d) did not panic", tc.w, tc.h)
				}
			}()
			New(tc.w, tc.h)
		}()
	}
}

func TestSetGet(t *testing.T) {
	c := New(4, 3)
	uassert.Equal(t, 4, c.Width())
	uassert.Equal(t, 3, c.Height())
	uassert.Equal(t, 0, c.Painted())
	uassert.Equal(t, Blank, c.Get(3, 2))

	c.Set(Pixel{X: 3, Y: 2, Color: 6})
	uassert.Equal(t, byte(6), c.Get(3, 2))
	uassert.Equal(t, 1, c.Painted())

	// Repainting the same pixel does not count twice.
	c.Set(Pixel{X: 3, Y: 2, Color: 7})
	uassert.Equal(t, byte(7), c.Get(3, 2))
	uassert.Equal(t, 1, c.Painted())

	// Other rows stay unallocated and blank.
	uassert.Equal(t, Blank, c.Get(0, 0))
	uassert.True(t, c.rows[0] == nil, "row 0 should stay nil")
}

func TestCheck(t *testing.T) {
	c := New(2, 2)
	tests := []struct {
		name string
		p    Pixel
		err  error
	}{
		{"ok", Pixel{0, 0, 1}, nil},
		{"ok max", Pixel{1, 1, MaxColor}, nil},
		{"x negative", Pixel{-1, 0, 1}, ErrOutOfRange},
		{"y negative", Pixel{0, -1, 1}, ErrOutOfRange},
		{"x too big", Pixel{2, 0, 1}, ErrOutOfRange},
		{"y too big", Pixel{0, 2, 1}, ErrOutOfRange},
		{"blank color", Pixel{0, 0, Blank}, ErrInvalidColor},
		{"color too big", Pixel{0, 0, MaxColor + 1}, ErrInvalidColor},
	}
	for _, tc := range tests {
		got := c.Check(tc.p)
		if got != tc.err {
			t.Errorf("%s: got %v, want %v", tc.name, got, tc.err)
		}
	}
}

func TestRows(t *testing.T) {
	c := New(3, 3)
	uassert.Equal(t, "000000000", c.Rows(0, 3))
	c.Set(Pixel{X: 1, Y: 1, Color: 15})
	c.Set(Pixel{X: 2, Y: 2, Color: 10})
	uassert.Equal(t, "000", c.Rows(0, 1))
	uassert.Equal(t, "0f0", c.Rows(1, 2))
	uassert.Equal(t, "0f000a", c.Rows(1, 3))
	uassert.Equal(t, "", c.Rows(2, 2))

	for _, r := range [][2]int{{-1, 1}, {0, 4}, {2, 1}} {
		func() {
			defer func() {
				if rec := recover(); rec == nil {
					t.Errorf("Rows(%d, %d) did not panic", r[0], r[1])
				}
			}()
			c.Rows(r[0], r[1])
		}()
	}
}

func TestParsePixels(t *testing.T) {
	px, err := ParsePixels("0,0,1;5,7,15;")
	uassert.NoError(t, err)
	uassert.Equal(t, 2, len(px))
	if px[0] != (Pixel{0, 0, 1}) || px[1] != (Pixel{5, 7, 15}) {
		t.Errorf("unexpected pixels: %v", px)
	}

	for _, bad := range []string{"", ";", "1,2", "1,2,3,4", "a,2,3", "1,b,3", "1,2,c", "1,2,0", "1,2,16", "1,2,-1"} {
		if _, err := ParsePixels(bad); err == nil {
			t.Errorf("ParsePixels(%q) accepted invalid input", bad)
		}
	}
}

func TestEncodeRoundTrip(t *testing.T) {
	in := []Pixel{{0, 0, 1}, {999, 999, 15}, {3, 4, 8}}
	s := Encode(in)
	uassert.Equal(t, "0,0,1;999,999,15;3,4,8", s)
	out, err := ParsePixels(s)
	uassert.NoError(t, err)
	uassert.Equal(t, len(in), len(out))
	for i := range in {
		if in[i] != out[i] {
			t.Errorf("pixel %d: got %v, want %v", i, out[i], in[i])
		}
	}
}

// Package million is a pay-per-pixel collaborative canvas: anyone can paint
// any pixel of a Width x Height grid in one of 15 colors by sending exactly
// Price() ugnot per pixel along with the call. Pixels can be repainted by
// anyone, for the same price. Payments are forwarded to the admin wallet
// as they arrive, and the admin paints for free.
//
// The grid logic lives in gno.land/p/g1sw5xklxjjuv0yvuxy5f5s3l3mnj0nqq626a9wr/canvas/v0; this realm adds the
// payment guard, the owner controls and the read API used by the web client.
package million

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/g1sw5xklxjjuv0yvuxy5f5s3l3mnj0nqq626a9wr/canvas/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	// Width and Height are fixed for the life of this version: changing
	// them would change the storage layout, so it means a new /vN.
	// 1250 x 800 is one million pixels in a 16:10 laptop aspect ratio.
	Width  = 1250
	Height = 800

	// MaxBatch bounds a single PaintBatch call so one tx cannot blow the
	// block gas limit or overflow the price arithmetic.
	MaxBatch = 500

	// DefaultPrice is the initial price per pixel, in ugnot (0.05 GNOT).
	DefaultPrice int64 = 50_000

	// DefaultAdmin receives every payment, paints for free and holds the
	// owner controls. Change it before deploying; TransferOwnership moves
	// it afterwards.
	DefaultAdmin = "g1sw5xklxjjuv0yvuxy5f5s3l3mnj0nqq626a9wr"

	Denom = "ugnot"
)

var (
	board = canvas.New(Width, Height)
	price = DefaultPrice
	owner = address(DefaultAdmin)

	// Stats.
	revenue int64 // total ugnot ever paid for pixels
	paints  int64 // number of successful Paint/PaintBatch calls

	// Change tracking, so clients fetch only the rows that moved.
	// version bumps once per successful paint call; rowVersion holds the
	// version of the last paint that touched each row (0 = never painted).
	version    int64
	rowVersion = make([]int64, Height)
)

// Paint colors one pixel. Send exactly Price() ugnot (nothing for the admin).
func Paint(cur realm, x, y, color int) {
	if color <= 0 || color > int(canvas.MaxColor) {
		panic(canvas.ErrInvalidColor)
	}
	paint([]canvas.Pixel{{X: x, Y: y, Color: byte(color)}}, cur)
}

// PaintBatch colors up to MaxBatch pixels in one call. The argument is
// "x,y,color;x,y,color;...". Send exactly Price() * count ugnot (nothing
// for the admin).
func PaintBatch(cur realm, pixels string) {
	px, err := canvas.ParsePixels(pixels)
	if err != nil {
		panic(err)
	}
	paint(px, cur)
}

// paint takes the realm as its LAST parameter on purpose: a realm first
// parameter would make it a crossing function and Previous() would then
// be this realm instead of the user.
func paint(px []canvas.Pixel, rlm realm) {
	if !rlm.IsCurrent() {
		panic("spoofed realm")
	}
	// Payment guard: unsafe.OriginSend() describes the coins attached to
	// the transaction, which only provably landed here when the caller is
	// a plain user call (no intermediate or ephemeral realm). Keep the two
	// checks together. unsafe is imported for OriginSend only; caller
	// identity always comes from the realm handle.
	if !rlm.Previous().IsUserCall() {
		panic("must be called directly by a user (maketx call)")
	}
	painter := rlm.Previous().Address()
	n := len(px)
	if n == 0 {
		panic("nothing to paint")
	}
	if n > MaxBatch {
		panic(ufmt.Sprintf("too many pixels: %d > %d", n, MaxBatch))
	}
	for _, p := range px {
		if err := board.Check(p); err != nil {
			panic(err)
		}
	}

	cost := price * int64(n)
	if painter == owner {
		cost = 0 // the admin paints for free
	}
	if sent := sentUgnot(unsafe.OriginSend()); sent != cost {
		panic(ufmt.Sprintf("must send exactly %d%s for %d pixel(s), got %d%s", cost, Denom, n, sent, Denom))
	}
	if cost > 0 {
		// Forward the payment to the admin right away, so nothing
		// accumulates in the realm. BankerTypeOriginSend can only move
		// what this very message sent, which is exactly cost.
		bnk := banker.NewBanker(banker.BankerTypeOriginSend, rlm)
		bnk.SendCoins(rlm.Address(), owner, chain.NewCoins(chain.NewCoin(Denom, cost)))
	}

	version++
	for _, p := range px {
		board.Set(p)
		rowVersion[p.Y] = version
	}
	revenue += cost
	paints++

	// The pixel list itself is not emitted: event attribute values are
	// size-capped by the node and a full batch exceeds it. Clients re-read
	// Rows() after a paint.
	chain.Emit("Paint",
		"painter", painter.String(),
		"count", strconv.Itoa(n),
		"paid", strconv.Itoa(int(cost))+Denom,
	)
}

// sentUgnot returns the ugnot amount in coins and rejects any other denom,
// so a caller cannot pay with something the realm does not price.
func sentUgnot(coins chain.Coins) int64 {
	var amount int64
	for _, c := range coins {
		if c.Denom != Denom {
			panic("only " + Denom + " is accepted")
		}
		amount += c.Amount
	}
	return amount
}

// --- owner controls ---

// assertOwner panics unless the verified caller behind rlm is the owner.
// The realm is deliberately not the first parameter (see paint); the
// leading blank int is the same idiom gno.land/p/nt/ownable uses.
func assertOwner(_ int, rlm realm) {
	if !rlm.IsCurrent() {
		panic("spoofed realm")
	}
	if rlm.Previous().Address() != owner {
		panic("owner only")
	}
}

// SetPrice changes the price per pixel, in ugnot. Zero makes painting free
// for everyone.
func SetPrice(cur realm, ugnot int64) {
	assertOwner(0, cur)
	if ugnot < 0 {
		panic("price must not be negative")
	}
	price = ugnot
}

// Withdraw sends amount ugnot held by the realm to the given address.
// Payments are forwarded on arrival, so this only matters for coins sent
// to the realm outside of a paint call.
func Withdraw(cur realm, to address, amount int64) {
	assertOwner(0, cur)
	if !to.IsValid() {
		panic("invalid address")
	}
	if amount <= 0 {
		panic("amount must be positive")
	}
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin(Denom, amount)))
}

// TransferOwnership hands the admin role (payments, free painting and the
// owner controls) to newOwner.
func TransferOwnership(cur realm, newOwner address) {
	assertOwner(0, cur)
	if !newOwner.IsValid() {
		panic("invalid address")
	}
	owner = newOwner
}

// --- read API (used by the web client through vm/qeval) ---

func GetWidth() int    { return Width }
func GetHeight() int   { return Height }
func Price() int64     { return price }
func Owner() address   { return owner }
func Painted() int     { return board.Painted() }
func Revenue() int64   { return revenue }
func Paints() int64    { return paints }
func MaxBatchSize() int { return MaxBatch }

// Pixel returns the color index at (x, y); 0 means never painted.
func Pixel(x, y int) int { return int(board.Get(x, y)) }

// Rows returns rows [from, to) as one hex digit per pixel, Width digits per
// row, with no separators. Clients page through the grid with it.
func Rows(from, to int) string { return board.Rows(from, to) }

// Version is the number of successful paint calls so far. Clients remember
// it and ask DirtyRows for what changed since.
func Version() int64 { return version }

// DirtyRows lists the rows painted after version `since`, as "y,y,y" in
// ascending order. DirtyRows(0) is every row that was ever painted, which
// is all a fresh client needs to load: the others are blank.
func DirtyRows(since int64) string {
	if since < 0 {
		since = 0
	}
	var sb strings.Builder
	for y, v := range rowVersion {
		if v <= since {
			continue
		}
		if sb.Len() > 0 {
			sb.WriteByte(',')
		}
		sb.WriteString(strconv.Itoa(y))
	}
	return sb.String()
}

// Palette returns the 16 palette colors as comma-separated CSS hex values,
// index 0 being the blank color.
func Palette() string {
	return strings.Join(canvas.Palette[:], ",")
}

// Render shows the game stats on gnoweb. The path is ignored.
func Render(_ string) string {
	var sb strings.Builder
	sb.WriteString("# Million Gno\n\n")
	sb.WriteString("A pay-per-pixel canvas. Pick a color, pay the price, own the pixel until someone repaints it. Payments go to the admin wallet, which paints for free.\n\n")
	sb.WriteString("| | |\n|---|---|\n")
	sb.WriteString(ufmt.Sprintf("| Size | %d x %d |\n", Width, Height))
	sb.WriteString(ufmt.Sprintf("| Price per pixel | %d%s |\n", price, Denom))
	sb.WriteString(ufmt.Sprintf("| Pixels painted | %d / %d |\n", board.Painted(), Width*Height))
	sb.WriteString(ufmt.Sprintf("| Paint calls | %d |\n", paints))
	sb.WriteString(ufmt.Sprintf("| Version | %d |\n", version))
	sb.WriteString(ufmt.Sprintf("| Revenue | %d%s |\n", revenue, Denom))
	sb.WriteString(ufmt.Sprintf("| Admin | %s |\n", owner.String()))
	sb.WriteString("\n## Palette\n\n")
	for i := 1; i <= int(canvas.MaxColor); i++ {
		sb.WriteString(ufmt.Sprintf("- %d: `%s`\n", i, canvas.Palette[i]))
	}
	sb.WriteString("\n## Paint\n\n")
	sb.WriteString("- [Paint one pixel](" + Realm + "$help&func=Paint): `Paint(x, y, color)` with `-send <price>ugnot`\n")
	sb.WriteString("- [Paint a batch](" + Realm + "$help&func=PaintBatch): `PaintBatch(\"x,y,color;x,y,color\")` with `-send <price*count>ugnot`\n")
	return sb.String()
}

// Realm is this realm's gnoweb path.
const Realm = "/r/g1sw5xklxjjuv0yvuxy5f5s3l3mnj0nqq626a9wr/million/v0"
